import React, { useState, useRef, useEffect } from 'react';
import { useEffectLogo, logoStijl } from '../components/EffectLogo';
import { TobRegel, AfrekeningBedrag } from '../components/Afrekening';
import { standaardTob, berekenTob } from '../utils/tob';
import KostenInvoer from '../components/KostenInvoer';
import { koers as koersFmt, koersInvoer } from '../utils/getal';
import { muntSymbool, MUNTEN } from '../utils/munt';
import { createPortal } from 'react-dom';
import { useApp } from '../context/AppContext';
import { Plus, ChevronDown, Calendar, MoreVertical, Search, ArrowLeft, X, Trash2, Download } from 'lucide-react';
import SidebarToggleKnop from '../components/SidebarToggleKnop';
import BeleggingDetail from '../components/BeleggingDetail';

import { getal } from '../utils/getal';
// ── kleine hulpfuncties ──────────────────────────────────────────
// ETF uitgever mapping → afkorting + kleur
const ETF_UITGEVERS = [
  { match: ['ishares','blackrock','ish '], label: 'iSH', kleur: '#00b140', tekst: 'white' },
  { match: ['vanguard','vang ftse','vang ','vang.'], label: 'VG', kleur: '#c8102e', tekst: 'white' },
  { match: ['amundi','lyx ','lyxor'], label: 'AM', kleur: '#0066cc', tekst: 'white' },
  { match: ['xtrackers','dws','xtr '], label: 'XT', kleur: '#003c88', tekst: 'white' },
  { match: ['invesco','inv '], label: 'IV', kleur: '#00205b', tekst: 'white' },
  { match: ['spdr','state street','spdrs'], label: 'SPD', kleur: '#00a651', tekst: 'white' },
  { match: ['wisdomtree','wt '], label: 'WT', kleur: '#f7941d', tekst: 'white' },
  { match: ['vaneck','van eck'], label: 'VE', kleur: '#003087', tekst: 'white' },
  { match: ['ubs'], label: 'UBS', kleur: '#e3000f', tekst: 'white' },
  { match: ['pimco'], label: 'PM', kleur: '#00205b', tekst: 'white' },
  { match: ['franklin','templeton'], label: 'FT', kleur: '#2e5eaa', tekst: 'white' },
  { match: ['fidelity'], label: 'FID', kleur: '#008a00', tekst: 'white' },
  { match: ['hsbc'], label: 'HSB', kleur: '#db0011', tekst: 'white' },
  { match: ['jpmorgan','jpm '], label: 'JPM', kleur: '#003087', tekst: 'white' },
  { match: ['goldman','gs '], label: 'GS', kleur: '#6699ff', tekst: 'white' },
  { match: ['msci'], label: 'MS', kleur: '#ff6600', tekst: 'white' },
];

// Crypto kleur mapping
const CRYPTO_KLEUREN = {
  'BTC': { kleur: '#f7931a', tekst: 'white' },
  'ETH': { kleur: '#627eea', tekst: 'white' },
  'SOL': { kleur: '#9945ff', tekst: 'white' },
  'XRP': { kleur: '#00aae4', tekst: 'white' },
  'ADA': { kleur: '#0033ad', tekst: 'white' },
  'DOT': { kleur: '#e6007a', tekst: 'white' },
  'DOGE': { kleur: '#c2a633', tekst: 'white' },
  'AVAX': { kleur: '#e84142', tekst: 'white' },
  'LINK': { kleur: '#2a5ada', tekst: 'white' },
  'MATIC': { kleur: '#8247e5', tekst: 'white' },
  'SHIB': { kleur: '#f00500', tekst: 'white' },
  'TON': { kleur: '#0088cc', tekst: 'white' },
};

function Avatar({ symbol, logo, naam, type }) {
  // Logo uit meerdere bronnen (zie components/EffectLogo.js)
  const { src: logoSrc, onError: logoFout, rond: logoRond, donker: logoDonker } = useEffectLogo({ symbol, logo, naam, type });
  const initials = symbol.split('.')[0].slice(0, 2).toUpperCase();

  if (logoSrc) {
    return (
      <img
        src={logoSrc} alt={symbol}
        style={logoStijl(36, logoRond ? '50%' : 10, logoDonker)}
        onError={logoFout}
      />
    );
  }

  // ETF badge op basis van uitgevende instelling
  const naamCheck = (naam || symbol || '').toLowerCase();
  const symCheck = (symbol || '').toUpperCase();
  
  // Ticker prefix mapping voor bekende ETF-families
  const TICKER_MAP = {
    'VWCE': 'VG', 'VFEM': 'VG', 'VUSA': 'VG', 'VEUR': 'VG', 'VHYL': 'VG',
    'VWRL': 'VG', 'VXUS': 'VG', 'VEVE': 'VG', 'VJPN': 'VG', 'VFEM': 'VG',
    'IWDA': 'iSH', 'CSPX': 'iSH', 'EIMI': 'iSH', 'IEMA': 'iSH', 'IMEA': 'iSH',
    'IUSA': 'iSH', 'IQQQ': 'iSH', 'ISAC': 'iSH', 'SPPW': 'iSH', 'SWRD': 'iSH',
    'EXSA': 'iSH', 'EXXT': 'iSH', 'EXH': 'iSH',
    'AMUN': 'AM', 'CW8': 'AM', 'PCEU': 'AM',
    'XDWD': 'XT', 'XMAW': 'XT', 'XNAS': 'XT', 'XESX': 'XT',
  };
  const tickerBase = symCheck.split('.')[0];
  const tickerLabel = TICKER_MAP[tickerBase];

  const isEtf = type === 'etf' || (!type && (
    ETF_UITGEVERS.some(u => u.match.some(m => naamCheck.includes(m))) || !!tickerLabel
  ));
  
  if (isEtf) {
    // Eerst op ticker
    if (tickerLabel) {
      const u = ETF_UITGEVERS.find(u => u.label === tickerLabel) || ETF_UITGEVERS.find(u => u.match[0] === (tickerLabel === 'VG' ? 'vanguard' : tickerLabel === 'iSH' ? 'ishares' : tickerLabel.toLowerCase()));
      const kleur = tickerLabel === 'VG' ? '#c8102e' : tickerLabel === 'iSH' ? '#00b140' : tickerLabel === 'AM' ? '#0066cc' : tickerLabel === 'XT' ? '#003c88' : '#1e3a8a';
      return (
        <div style={{ width: 36, height: 36, borderRadius: 10, flexShrink: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', background: kleur, color: 'white', fontWeight: 800, fontSize: 10, letterSpacing: '-0.3px' }}>
          {tickerLabel}
        </div>
      );
    }
    const uitgever = ETF_UITGEVERS.find(u => u.match.some(m => naamCheck.includes(m)));
    if (uitgever) {
      return (
        <div style={{
          width: 36, height: 36, borderRadius: 10, flexShrink: 0,
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          background: uitgever.kleur, color: uitgever.tekst,
          fontWeight: 800, fontSize: 10, letterSpacing: '-0.3px',
        }}>
          {uitgever.label}
        </div>
      );
    }
    // Generieke ETF badge
    return (
      <div style={{ width: 36, height: 36, borderRadius: 10, flexShrink: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', background: '#1e3a8a', color: 'white', fontWeight: 800, fontSize: 9 }}>
        ETF
      </div>
    );
  }

  // Crypto badge met eigen kleur
  const basis = symbol.replace(/-EUR$|-USD$|-GBP$|-USDT$/,'').toUpperCase();
  const isCrypto = type === 'crypto' || (!type && CRYPTO_KLEUREN[basis]);
  
  if (isCrypto) {
    const cryptoKleur = CRYPTO_KLEUREN[basis] || { kleur: '#f7931a', tekst: 'white' };
    return (
      <div style={{
        width: 36, height: 36, borderRadius: 10, flexShrink: 0,
        display: 'flex', alignItems: 'center', justifyContent: 'center',
        background: cryptoKleur.kleur, color: cryptoKleur.tekst,
        fontWeight: 800, fontSize: 12,
      }}>
        {basis.slice(0, 3)}
      </div>
    );
  }

  // Standaard fallback
  return (
    <div style={{
      width: 36, height: 36, borderRadius: 10, background: 'var(--accent-bg)',
      color: 'var(--accent)', fontWeight: 700, fontSize: 13, flexShrink: 0,
      display: 'flex', alignItems: 'center', justifyContent: 'center'
    }}>
      {initials}
    </div>
  );
}

function KebabMenu({ onDetail, onVerkopen, onVerwijder }) {
  const { t } = useApp();
  const [open, setOpen] = useState(false);
  const [positie, setPositie] = useState(null);
  const ref = useRef();
  const knopRef = useRef();

  useEffect(() => {
    const handle = (e) => {
      if (ref.current && !ref.current.contains(e.target) && !e.target.closest('[data-kebab-menu]')) setOpen(false);
    };
    document.addEventListener('mousedown', handle);
    return () => document.removeEventListener('mousedown', handle);
  }, []);

  const toggleOpen = (e) => {
    e.stopPropagation();
    if (!open && knopRef.current) {
      const rect = knopRef.current.getBoundingClientRect();
      setPositie({ top: rect.bottom + 4, right: window.innerWidth - rect.right });
    }
    setOpen(o => !o);
  };

  return (
    <div ref={ref} style={{ position: 'relative' }}>
      <button
        ref={knopRef}
        onClick={toggleOpen}
        style={{ background: 'transparent', border: 'none', cursor: 'pointer', padding: '4px 6px',
          borderRadius: 6, color: 'var(--text-muted)', display: 'flex', alignItems: 'center' }}
      >
        <MoreVertical size={16} />
      </button>
      {open && positie && createPortal(
        <div data-kebab-menu style={{
          position: 'fixed', top: positie.top, right: positie.right, background: 'var(--bg-white)',
          border: '1px solid var(--border)', borderRadius: 10, boxShadow: 'var(--shadow-md)',
          zIndex: 1000, minWidth: 160, overflow: 'hidden'
        }}>
          <button onClick={e => { e.stopPropagation(); setOpen(false); onDetail(); }}
            style={menuItemStyle}>{t('bel_detail_bekijken')}</button>
          <button onClick={e => { e.stopPropagation(); setOpen(false); onVerkopen(); }}
            style={menuItemStyle}>{t('bel_verkoop_registreren')}</button>
          <div style={{ height: 1, background: 'var(--border-light)' }} />
          <button onClick={e => { e.stopPropagation(); setOpen(false); onVerwijder(); }}
            style={{ ...menuItemStyle, color: 'var(--red)' }}>{t('bel_verwijderen')}</button>
        </div>,
        document.body
      )}
    </div>
  );
}

const menuItemStyle = {
  display: 'block', width: '100%', textAlign: 'left', background: 'transparent',
  border: 'none', padding: '10px 16px', fontSize: 13, cursor: 'pointer',
  fontFamily: 'inherit', color: 'var(--text-primary)',
  transition: 'background 0.1s'
};

// ── Beurstaks (TOB) bij verkoop, België ──────────────────────────
// Tarief en maximum per transactie (in euro).

// ── Verkoop Registreren Modal ────────────────────────────────────
function VerkoopModal({ beleggingen, koersen, onClose, onBevestig }) {
  const { t, getMuntFactor, fxOp, profielInfo } = useApp();
  const [kostenMunt, setKostenMunt] = useState('EUR'); // munt waarin de broker de kosten aanrekent
  const [ontvangen, setOntvangen] = useState(''); // werkelijk ontvangen volgens de afrekening (€), optioneel
  const [kosten, setKosten] = useState('');          // transactiekosten broker
  const [tobId, setTobId] = useState('0.35');
  const [tobHandmatig, setTobHandmatig] = useState(null); // zelf aangepast bedrag
  const [stap, setStap] = useState('kiezen'); // 'kiezen' | 'invullen'
  const [zoek, setZoek] = useState('');
  const [gekozen, setGekozen] = useState(null);
  const [form, setForm] = useState({ datum: new Date().toISOString().slice(0, 10), aantal: '', koers: '', munt: 'EUR', verkoopbedrag: '' });
  const [beperkteInfoVerkoop, setBeperkteInfoVerkoop] = useState(false);
  const [aantalOnbekend, setAantalOnbekend] = useState(false);
  const [historischLoading, setHistorischLoading] = useState(false);
  const [historischeFout, setHistorischeFout] = useState('');

  // Pre-fill koers als beschikbaar
  useEffect(() => {
    if (gekozen) {
      const k = koersen[gekozen.symbol];
      const koers = koersInvoer(k ? k.c : gekozen.kostprijs);
      const munt = gekozen.munt || 'EUR';
      setForm({
        datum: new Date().toISOString().slice(0, 10),
        aantal: gekozen.aantal.toString(),
        koers,
        munt
      });
      setKosten('');
      setKostenMunt('EUR');
      setOntvangen('');
      setTobId(standaardTob(gekozen, profielInfo?.[gekozen.symbol]));
      setTobHandmatig(null);
      setStap('invullen');
    }
  }, [gekozen]);

  const gefilterd = beleggingen.filter(b =>
    b.naam.toLowerCase().includes(zoek.toLowerCase()) ||
    b.symbol.toLowerCase().includes(zoek.toLowerCase())
  );

  // Zelfde gemiddelde kostenpercentages als bij "Beperkte info" bij aankoop.
  const GEMIDDELD_KOSTENPERCENTAGE = { aandeel: 0.01, etf: 0.005 };

  const haalHistorischeKoers = async (symbol, datumStr) => {
    const doelDatum = new Date(datumStr);
    const van = Math.floor(doelDatum.getTime() / 1000) - 5 * 24 * 60 * 60;
    const tot = Math.floor(doelDatum.getTime() / 1000) + 24 * 60 * 60;
    try {
      const res = await fetch(`/api/data?endpoint=candle&symbol=${encodeURIComponent(symbol)}&van=${van}&tot=${tot}&resolutie=D`);
      const data = await res.json();
      if (data?.s === 'ok' && data?.c?.length > 0) return data.c[data.c.length - 1];
    } catch (e) {}
    return null;
  };

  // Bij het kiezen van een verkoopdatum: automatisch de slotkoers van die dag
  // opzoeken en invullen — de gebruiker kan die waarde nadien nog altijd zelf
  // aanpassen. Bij "beperkte info" gebeurt de koers-opzoeking pas bij het
  // bevestigen (die flow gebruikt de koers anders, om het aantal te schatten).
  const kiesDatum = async (nieuweDatumStr) => {
    setForm(f => ({ ...f, datum: nieuweDatumStr }));
    if (beperkteInfoVerkoop || !nieuweDatumStr) return;
    setHistorischLoading(true);
    setHistorischeFout('');
    const prijs = await haalHistorischeKoers(gekozen.symbol, nieuweDatumStr);
    if (prijs) {
      setForm(f => ({ ...f, koers: koersInvoer(prijs) }));
    } else {
      setHistorischeFout('Kon de koers van die dag niet automatisch ophalen — vul zelf in.');
    }
    setHistorischLoading(false);
  };

  // Verkoopbedrag in de munt van het effect; kosten en beurstaks in euro
  // (Belgische brokers rekenen in euro, en de TOB is een Belgische belasting
  // in euro, berekend op het verkoopbedrag in euro). Bij het opslaan worden
  // ze omgerekend naar de munt van de verkoop, zodat alle berekeningen in de
  // app blijven kloppen.
  const brutoBedrag = beperkteInfoVerkoop
    ? (parseFloat(form.verkoopbedrag) || 0)
    : (parseFloat(form.aantal) || 0) * (parseFloat(form.koers) || 0);
  const munt = form.munt || 'EUR';
  const naarEur = munt === 'EUR' ? 1
    : ((fxOp ? fxOp(munt, form.datum) : 0) || (getMuntFactor ? getMuntFactor(munt) : 1) || 1);
  const brutoEur = brutoBedrag * naarEur;
  const tobAuto = berekenTob(brutoEur, tobId);
  const tobEur = tobHandmatig != null && tobHandmatig !== '' ? (parseFloat(tobHandmatig) || 0) : tobAuto;
  const kostenIngevuld = parseFloat(kosten) || 0;
  const kostenEur = kostenMunt === 'EUR' ? kostenIngevuld : kostenIngevuld * naarEur;
  const nettoEur = brutoEur - kostenEur - tobEur;
  // Werkelijk ontvangen (volgens de afrekening van de broker): als ingevuld,
  // gebruikt de app exact dat bedrag. De broker rekent om aan zijn eigen koers
  // (en verrekent wisselkoerskosten soms al in die koers), terwijl de app de
  // ECB-dagkoers gebruikt — daardoor kan de berekening enkele centen afwijken.
  const ontvangenEur = parseFloat(ontvangen) > 0 ? parseFloat(ontvangen) : null;
  const extraKosten = { verkoopkosten: kostenEur / naarEur, tob: tobEur / naarEur, ...(ontvangenEur ? { ontvangenEur } : {}) };

  const bevestig = async () => {
    if (beperkteInfoVerkoop && aantalOnbekend) {
      // Aantal is niet gekend — enkel verkoopbedrag + datum. Net als bij
      // "Beperkte info" bij aankoop: zoek de historische koers op die datum
      // op, en schat op basis daarvan hoeveel stuks er verkocht werden
      // (rekening houdend met een realistisch gemiddeld kostenpercentage —
      // bij verkoop verminderen kosten net je netto-ontvangen bedrag).
      if (!form.datum || !form.verkoopbedrag) return;
      setHistorischeFout('');
      setHistorischLoading(true);
      const verkoopbedrag = parseFloat(form.verkoopbedrag);
      const historischeKoers = await haalHistorischeKoers(gekozen.symbol, form.datum);
      setHistorischLoading(false);
      if (!historischeKoers || historischeKoers <= 0) {
        setHistorischeFout('Geen historische koers gevonden voor deze datum. Vul het aantal handmatig in.');
        return;
      }
      const kostenPct = GEMIDDELD_KOSTENPERCENTAGE[gekozen.type] ?? 0.01;
      const geschatAantalRuw = Math.round(verkoopbedrag / (historischeKoers * (1 - kostenPct)));
      const geschatAantal = Math.min(Math.max(1, geschatAantalRuw), gekozen.aantal);
      onBevestig(gekozen, {
        datum: form.datum,
        aantal: geschatAantal,
        koers: verkoopbedrag / geschatAantal,
        munt: form.munt,
        ...extraKosten,
      });
      onClose();
      return;
    }
    if (beperkteInfoVerkoop) {
      if (!form.datum || !form.aantal || !form.verkoopbedrag) return;
      const aantalGetal = parseFloat(form.aantal);
      onBevestig(gekozen, {
        datum: form.datum,
        aantal: aantalGetal,
        koers: parseFloat(form.verkoopbedrag) / aantalGetal,
        munt: form.munt,
        ...extraKosten,
      });
      onClose();
      return;
    }
    if (!form.datum || !form.aantal || !form.koers) return;
    onBevestig(gekozen, {
      datum: form.datum,
      aantal: parseFloat(form.aantal),
      koers: parseFloat(form.koers),
      munt: form.munt,
      ...extraKosten,
    });
    onClose();
  };

  return (
    <div style={{
      position: 'fixed', inset: 0, background: 'rgba(15,23,42,0.4)',
      display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000
    }} onClick={onClose}>
      <div style={{
        background: 'var(--bg-white)', borderRadius: 16, padding: '32px',
        width: 520, maxWidth: '90vw', maxHeight: '90vh', overflowY: 'auto', boxShadow: 'var(--shadow-lg)', position: 'relative'
      }} onClick={e => e.stopPropagation()}>
        {/* Sluitknop */}
        <button onClick={onClose} style={{
          position: 'absolute', top: 16, right: 16, background: 'transparent',
          border: 'none', cursor: 'pointer', color: 'var(--text-muted)', padding: 4
        }}><X size={20} /></button>

        <h2 style={{ fontSize: 20, fontWeight: 700, marginBottom: 6 }}>{t('bel_verkoop_registreren')}</h2>

        {stap === 'kiezen' ? (
          <>
            <p style={{ color: 'var(--text-secondary)', fontSize: 14, marginBottom: 20 }}>
              {t('bel_modal_kies_tekst')}
            </p>
            {/* Zoekbalk */}
            <div style={{ position: 'relative', marginBottom: 16 }}>
              <Search size={16} style={{ position: 'absolute', left: 14, top: '50%', transform: 'translateY(-50%)', color: 'var(--text-muted)' }} />
              <input
                autoFocus
                value={zoek}
                onChange={e => setZoek(e.target.value)}
                placeholder={t('bel_zoek_placeholder')}
                style={{
                  width: '100%', padding: '10px 14px 10px 40px',
                  border: '1.5px solid var(--border)', borderRadius: 10,
                  fontSize: 14, fontFamily: 'inherit', outline: 'none',
                  color: 'var(--text-primary)', background: 'var(--bg)'
                }}
              />
            </div>
            {/* Lijst */}
            <div style={{ border: '1px solid var(--border)', borderRadius: 12, overflowY: 'auto', maxHeight: '45vh', marginBottom: 20 }}>
              {gefilterd.length === 0 ? (
                <div style={{ padding: '20px', textAlign: 'center', color: 'var(--text-muted)', fontSize: 13 }}>
                  {t('bel_geen_beleggingen_gevonden')}
                </div>
              ) : gefilterd.map((b, i) => (
                <div key={b.id}
                  onClick={() => setGekozen(b)}
                  style={{
                    display: 'flex', alignItems: 'center', gap: 14, padding: '14px 16px',
                    cursor: 'pointer', borderBottom: i < gefilterd.length - 1 ? '1px solid var(--border-light)' : 'none',
                    transition: 'background 0.1s'
                  }}
                  onMouseEnter={e => e.currentTarget.style.background = 'var(--bg)'}
                  onMouseLeave={e => e.currentTarget.style.background = 'transparent'}
                >
                  <Avatar symbol={b.symbol} logo={b.logo} naam={b.naam} type={b.type} />
                  <div style={{ flex: 1 }}>
                    <div style={{ fontWeight: 600, fontSize: 14 }}>{b.naam}</div>
                    <div style={{ fontSize: 12, color: 'var(--text-muted)' }}>
                      {b.symbol} · {b.aantal} {b.aantal !== 1 ? t('bel_stuk_mv') : t('bel_stuk_ev')}
                    </div>
                  </div>
                  <ChevronDown size={16} style={{ color: 'var(--text-muted)', transform: 'rotate(-90deg)' }} />
                </div>
              ))}
            </div>
            <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
              <button onClick={onClose} style={{
                padding: '10px 20px', border: '1px solid var(--border)', borderRadius: 8,
                background: 'transparent', cursor: 'pointer', fontFamily: 'inherit', fontSize: 14, fontWeight: 500
              }}>{t('ov_annuleren')}</button>
            </div>
          </>
        ) : (
          <>
            <p style={{ color: 'var(--text-secondary)', fontSize: 14, marginBottom: 16 }}>
              {t('bel_vul_verkoopgegevens')} <strong>{gekozen.naam} ({gekozen.symbol})</strong>
            </p>
            <div style={{ display: 'flex', justifyContent: 'flex-end', marginBottom: 16 }}>
              <button
                onClick={() => setBeperkteInfoVerkoop(v => !v)}
                style={{
                  background: beperkteInfoVerkoop ? 'var(--accent-bg)' : 'transparent',
                  color: beperkteInfoVerkoop ? 'var(--accent)' : 'var(--text-muted)',
                  border: '1px solid var(--border)', borderRadius: 8, padding: '6px 12px',
                  fontSize: 12, fontWeight: 600, cursor: 'pointer', fontFamily: 'inherit',
                }}
              >
                {beperkteInfoVerkoop ? '✓ ' : ''}Beperkte info (enkel verkoopbedrag gekend)
              </button>
            </div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
              {/* Verkoopdatum */}
              <div>
                <label style={{ display: 'block', fontSize: 13, fontWeight: 600, marginBottom: 6 }}>{t('bel_col_verkoopdatum')}</label>
                <input
                  type="date"
                  value={form.datum}
                  max={new Date().toISOString().slice(0, 10)}
                  onChange={e => kiesDatum(e.target.value)}
                  style={inputStyle}
                />
              </div>
              {/* Aantal */}
              {!(beperkteInfoVerkoop && aantalOnbekend) && (
                <div>
                  <label style={{ display: 'block', fontSize: 13, fontWeight: 600, marginBottom: 6 }}>{t('bel_col_aantal')}</label>
                  <input
                    type="number"
                    value={form.aantal}
                    onChange={e => setForm(f => ({ ...f, aantal: e.target.value }))}
                    style={inputStyle}
                  />
                </div>
              )}
              {beperkteInfoVerkoop && (
                <label style={{ display: 'flex', alignItems: 'center', gap: 8, cursor: 'pointer', fontSize: 13, color: 'var(--text-secondary)' }}>
                  <input type="checkbox" checked={aantalOnbekend}
                    onChange={e => setAantalOnbekend(e.target.checked)} />
                  Ik weet het aantal ook niet meer (enkel verkoopbedrag + datum gekend)
                </label>
              )}
              {!beperkteInfoVerkoop ? (
                <div>
                  <label style={{ display: 'block', fontSize: 13, fontWeight: 600, marginBottom: 6 }}>{t('bel_verkoopkoers_per_stuk')}</label>
                  <div style={{ display: 'flex', gap: 8 }}>
                    <input
                      type="number"
                      value={form.koers}
                      onChange={e => setForm(f => ({ ...f, koers: e.target.value }))}
                      style={{ ...inputStyle, flex: 1 }}
                    />
                    <select value={form.munt} onChange={e => setForm(f => ({ ...f, munt: e.target.value }))}
                      style={{ ...inputStyle, width: 80 }}>
                      {MUNTEN.map(m => <option key={m}>{m}</option>)}
                    </select>
                  </div>
                  {historischLoading ? (
                    <p style={{ fontSize: 12, color: 'var(--text-muted)', marginTop: 6 }}>Koers van die dag opzoeken...</p>
                  ) : historischeFout ? (
                    <p style={{ fontSize: 12, color: 'var(--red)', marginTop: 6 }}>{historischeFout}</p>
                  ) : (
                    <p style={{ fontSize: 12, color: 'var(--text-muted)', marginTop: 6 }}>
                      {t('bel_ingevuld_op_basis')} {new Date(form.datum).toLocaleDateString('nl-BE')} — pas gerust aan indien nodig.
                    </p>
                  )}
                </div>
              ) : (
                <div>
                  <label style={{ display: 'block', fontSize: 13, fontWeight: 600, marginBottom: 6 }}>Verkoopbedrag (totaal)</label>
                  <div style={{ display: 'flex', gap: 8 }}>
                    <input
                      type="number"
                      value={form.verkoopbedrag}
                      onChange={e => setForm(f => ({ ...f, verkoopbedrag: e.target.value }))}
                      style={{ ...inputStyle, flex: 1 }}
                      placeholder="€ 0,00"
                    />
                    <select value={form.munt} onChange={e => setForm(f => ({ ...f, munt: e.target.value }))}
                      style={{ ...inputStyle, width: 80 }}>
                      {MUNTEN.map(m => <option key={m}>{m}</option>)}
                    </select>
                  </div>
                  {!aantalOnbekend ? (
                    <p style={{ fontSize: 12, color: 'var(--text-muted)', marginTop: 6 }}>
                      We rekenen de verkoopkoers per stuk terug ({t('bel_col_aantal').toLowerCase()} × koers = verkoopbedrag).
                    </p>
                  ) : (
                    <p style={{ fontSize: 12, color: 'var(--text-muted)', marginTop: 6 }}>
                      We zoeken de historische koers op deze datum op en <strong>schatten</strong> hoeveel stuks er verkocht werden (afgerond naar een geheel getal, nooit meer dan wat je nog in bezit hebt).
                    </p>
                  )}
                  {historischeFout && (
                    <p style={{ fontSize: 12, color: 'var(--red)', marginTop: 6 }}>{historischeFout}</p>
                  )}
                </div>
              )}

              {/* Transactiekosten (de beurstaks wordt automatisch berekend, zie samenvatting) */}
              <div>
                <label style={{ display: 'block', fontSize: 13, fontWeight: 600, marginBottom: 6 }}>Transactiekosten <span style={{ fontWeight: 400, fontSize: 12, color: 'var(--text-muted)' }}>optioneel</span></label>
                <KostenInvoer value={kosten} onChange={setKosten} tobApart inputStyle={inputStyle}
                  naast={munt !== 'EUR' && (
                    <select value={kostenMunt} onChange={e => setKostenMunt(e.target.value)} style={{ ...inputStyle, width: 76 }}>
                      <option value="EUR">EUR</option>
                      <option value={munt}>{munt}</option>
                    </select>
                  )} />
              </div>

              {/* Samenvatting */}
              {brutoBedrag > 0 && (() => {
                const f2 = (v) => v.toLocaleString('nl-BE', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
                const rij = { display: 'flex', justifyContent: 'space-between', gap: 16, padding: '4px 0' };
                const num = { fontVariantNumeric: 'tabular-nums', whiteSpace: 'nowrap' };
                return (
                  <div style={{ padding: '8px 14px', background: 'var(--bg)', borderRadius: 10, fontSize: 13, color: 'var(--text-secondary)' }}>
                    <div style={rij}>
                      <span>Verkoopbedrag</span>
                      <span style={{ ...num, color: 'var(--text-primary)' }}>
                        {munt !== 'EUR' && <span style={{ color: 'var(--text-muted)', marginRight: 6 }}>{muntSymbool(munt)}{f2(brutoBedrag)} ≈</span>}
                        €{f2(brutoEur)}
                      </span>
                    </div>
                    <div style={rij}><span>Transactiekosten</span><span style={num}>− €{f2(kostenEur)}</span></div>
                    <TobRegel teken="−" tobId={tobId} setTobId={setTobId} tobEur={tobEur} tobHandmatig={tobHandmatig} setTobHandmatig={setTobHandmatig} inputStyle={inputStyle} />
                    <div style={{ ...rij, borderTop: '1px solid var(--border)', marginTop: 4, paddingTop: 8, fontWeight: 600, color: 'var(--text-primary)' }}>
                      <span>{ontvangenEur ? 'Berekend netto' : 'Netto ontvangen'}</span><span style={num}>€{f2(nettoEur)}</span>
                    </div>
                    {munt !== 'EUR' && (
                      <div style={{ fontSize: 11, color: 'var(--text-muted)', marginTop: 4 }}>
                        Omgerekend aan 1 {munt} = €{naarEur.toLocaleString('nl-BE', { maximumFractionDigits: 4 })} op {new Date(form.datum).toLocaleDateString('nl-BE')} (ECB-dagkoers).
                      </div>
                    )}
                    <AfrekeningBedrag label="Werkelijk ontvangen volgens je afrekening (€)" value={ontvangen} onChange={setOntvangen} berekend={nettoEur} inputStyle={inputStyle} />
                  </div>
                );
              })()}
            </div>
            <div style={{ display: 'flex', gap: 10, justifyContent: 'flex-end', marginTop: 24 }}>
              <button onClick={() => setStap('kiezen')} style={{
                padding: '10px 20px', border: '1px solid var(--border)', borderRadius: 8,
                background: 'transparent', cursor: 'pointer', fontFamily: 'inherit', fontSize: 14, fontWeight: 500
              }}>{t('bel_terug')}</button>
              <button onClick={bevestig} disabled={historischLoading} style={{
                padding: '10px 24px', background: 'var(--accent)', color: 'white',
                border: 'none', borderRadius: 8, cursor: 'pointer', fontFamily: 'inherit',
                fontSize: 14, fontWeight: 600
              }}>{historischLoading ? 'Koers opzoeken...' : t('bel_markeren_verkocht')}</button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

const inputStyle = {
  width: '100%', padding: '10px 14px', border: '1.5px solid var(--border)',
  borderRadius: 8, fontSize: 14, fontFamily: 'inherit', outline: 'none',
  color: 'var(--text-primary)', background: 'var(--bg-white)'
};

// ── Hoofd component ──────────────────────────────────────────────
export default function Beleggingen({ onToevoegen, sidebarCollapsed, onToggleSidebar }) {
  const { gebruiker, beleggingen, setBeleggingen, koersen, verkochteBeleggingen, setVerkochteBeleggingen, getMuntFactor, fxOp, kostEur, t } = useApp();
  // Gsm: compacte kaart per belegging i.p.v. de tabel (die viel uiteen in losse vakjes)
  const [isMobiel, setIsMobiel] = useState(typeof window !== 'undefined' && window.innerWidth < 768);
  useEffect(() => {
    const opResize = () => setIsMobiel(window.innerWidth < 768);
    window.addEventListener('resize', opResize);
    return () => window.removeEventListener('resize', opResize);
  }, []);

  // Haal logo's en type op voor beleggingen zonder logo OF zonder type
  React.useEffect(() => {
    const zonderInfo = [
      ...beleggingen.filter(b => !b.logo || !b.type),
      ...(verkochteBeleggingen || []).filter(b => !b.logo || !b.type)
    ];
    // Dedupliceer op symbol
    const gezien = new Set();
    const uniek = zonderInfo.filter(b => { if (gezien.has(b.symbol)) return false; gezien.add(b.symbol); return true; });
    uniek.forEach(async (b) => {
      try {
        const res = await fetch(`/api/data?endpoint=profile&symbol=${encodeURIComponent(b.symbol)}`);
        const data = await res.json();
        const logo = data.logo || data.image || '';
        const type = data.type || '';
        setBeleggingen(prev => prev.map(pb => pb.symbol === b.symbol ? {
          ...pb,
          ...(logo && !pb.logo ? { logo } : {}),
          ...(type && !pb.type ? { type } : {})
        } : pb));
        setVerkochteBeleggingen(prev => (prev || []).map(pb => pb.symbol === b.symbol ? {
          ...pb,
          ...(logo && !pb.logo ? { logo } : {}),
          ...(type && !pb.type ? { type } : {})
        } : pb));
      } catch (e) {}
    });
  }, [beleggingen.map(b => b.symbol + (b.type||'')).join(',')]);
  const [tab, setTab] = useState('actief');
  const [detailBelegging, setDetailBelegging] = useState(null);
  const [verkoopModal, setVerkoopModal] = useState(false);
  const [verkoopVoorBelegging, setVerkoopVoorBelegging] = useState(null);
  const [sortCol, setSortCol] = useState('datum');
  const [sortDir, setSortDir] = useState('asc');

  const wisselSort = (col) => {
    if (sortCol === col) setSortDir(d => d === 'asc' ? 'desc' : 'asc');
    else { setSortCol(col); setSortDir('asc'); }
  };
  const sortPijl = (col) => sortCol === col ? (sortDir === 'asc' ? '↑' : '↓') : '↕';

  const parseDatum = (s) => { if (!s) return 0; const d = s.split('/'); return d.length === 3 ? new Date(`${d[2]}-${d[1]}-${d[0]}`).getTime() : new Date(s).getTime(); };

  const gesorteerd = (lijst) => [...lijst].sort((a, b) => {
    let va, vb;
    switch (sortCol) {
      case 'naam': va = a.naam?.toLowerCase(); vb = b.naam?.toLowerCase(); break;
      case 'datum': va = parseDatum(a.datum); vb = parseDatum(b.datum); break;
      case 'kostprijs': va = a.kostprijs; vb = b.kostprijs; break;
      case 'aantal': va = a.aantal; vb = b.aantal; break;
      default: va = parseDatum(a.datum); vb = parseDatum(b.datum);
    }
    if (va < vb) return sortDir === 'asc' ? -1 : 1;
    if (va > vb) return sortDir === 'asc' ? 1 : -1;
    return 0;
  });

  const verwijder = (id) => {
    if (window.confirm(t('bel_belegging_verwijderen_confirm'))) {
      setBeleggingen(prev => prev.filter(b => b.id !== id));
    }
  };

  const openVerkoopModal = (belegging = null) => {
    setVerkoopVoorBelegging(belegging);
    setVerkoopModal(true);
  };

  const registreerVerkoop = (belegging, verkoopdata) => {
    const fractie = belegging.aantal > 0 ? verkoopdata.aantal / belegging.aantal : 1;
    const kostenVerkochtDeel = (belegging.transactiekosten || 0) * fractie;
    const verkochte = {
      ...belegging,
      transactiekosten: kostenVerkochtDeel,
      verkoopdatum: verkoopdata.datum,
      aantalVerkocht: verkoopdata.aantal,
      verkoopkoers: verkoopdata.koers,
      verkoopMunt: verkoopdata.munt,
      // Kosten bij verkoop (in de munt van de verkoop): broker + beurstaks
      verkoopkosten: verkoopdata.verkoopkosten || 0,
      tob: verkoopdata.tob || 0,
      // Exact ontvangen bedrag in euro (indien ingevuld): heeft voorrang
      ...(verkoopdata.ontvangenEur ? { ontvangenEur: verkoopdata.ontvangenEur } : {}),
      // (in de munt van het effect; met het exact ontvangen bedrag als dat gekend is)
      winstverlies: verkoopdata.ontvangenEur
        ? verkoopdata.ontvangenEur / ((fxOp ? fxOp(verkoopdata.munt || belegging.munt || 'EUR', verkoopdata.datum) : 1) || 1)
          - belegging.kostprijs * verkoopdata.aantal - kostenVerkochtDeel
        : (verkoopdata.koers - belegging.kostprijs) * verkoopdata.aantal - kostenVerkochtDeel
          - (verkoopdata.verkoopkosten || 0) - (verkoopdata.tob || 0)
    };
    setVerkochteBeleggingen(prev => [...(prev || []), verkochte]);
    // Verwijder (deels) uit actieve beleggingen
    setBeleggingen(prev => {
      const updated = prev.map(b => {
        if (b.id !== belegging.id) return b;
        const resterend = b.aantal - verkoopdata.aantal;
        if (resterend <= 0) return null;
        // Het overblijvende deel behoudt enkel zijn eigen aandeel van de
        // oorspronkelijke transactiekosten (de rest ging mee naar de verkoop hierboven).
        return { ...b, aantal: resterend, transactiekosten: (belegging.transactiekosten || 0) - kostenVerkochtDeel };
      }).filter(Boolean);
      return updated;
    });
  };

  const exporteerNaarExcel = () => {
    const nu = new Date();
    const datumStr = `${nu.getDate().toString().padStart(2,'0')}-${(nu.getMonth()+1).toString().padStart(2,'0')}-${nu.getFullYear()}`;
    const tijdStr = `${nu.getHours().toString().padStart(2,'0')}_${nu.getMinutes().toString().padStart(2,'0')}_${nu.getSeconds().toString().padStart(2,'0')}`;

    // Dynamisch xlsx importeren
    import('xlsx').then(XLSX => {
      const wb = XLSX.utils.book_new();

      // ── Sheet 1: Actieve posities ──
      const positieData = [
        ['Instrument','Valuta','Aantal','Aankoopkoers','Huidige koers','Aankoopwaarde (€)','Huidige waarde (€)','Winst/Verlies (€)','Winst/Verlies (%)','ISIN','Type','Aankoopdatum'],
        ...beleggingen.map(b => {
          const k = koersen[b.symbol];
          const factor = getMuntFactor(b.munt || 'EUR');
          const koersNu = k ? k.c : b.kostprijs;
          const aankoopWaarde = (b.kostprijs * b.aantal + (b.transactiekosten || 0)) * factor;
          const huidigeWaarde = koersNu * b.aantal * factor;
          const winstVerlies = huidigeWaarde - aankoopWaarde;
          const winstPct = aankoopWaarde > 0 ? (winstVerlies / aankoopWaarde) * 100 : 0;
          return [
            b.naam || b.symbol,
            b.munt || 'EUR',
            b.aantal,
            b.kostprijs,
            koersNu,
            parseFloat(aankoopWaarde.toFixed(2)),
            parseFloat(huidigeWaarde.toFixed(2)),
            parseFloat(winstVerlies.toFixed(2)),
            parseFloat(winstPct.toFixed(2)),
            '',
            b.type === 'etf' ? 'ETF' : b.type === 'crypto' ? 'Crypto' : 'Aandeel',
            b.datum || '',
          ];
        })
      ];
      const ws1 = XLSX.utils.aoa_to_sheet(positieData);
      ws1['!cols'] = [30,8,8,12,12,16,16,16,14,14,10,12].map(w => ({ wch: w }));
      XLSX.utils.book_append_sheet(wb, ws1, 'Posities');

      // ── Sheet 2: Transactiegeschiedenis ──
      const transactieData = [
        ['Datum','Type','Instrument','Symbool','Valuta','Aantal','Koers','Transactiekosten','Totaal (€)'],
        // Aankopen (actieve beleggingen)
        ...beleggingen.map(b => {
          const factor = getMuntFactor(b.munt || 'EUR');
          return [
            b.datum || '',
            'Aankoop',
            b.naam || b.symbol,
            b.symbol,
            b.munt || 'EUR',
            b.aantal,
            b.kostprijs,
            b.transactiekosten || 0,
            parseFloat((b.kostprijs * b.aantal * factor + (b.transactiekosten || 0)).toFixed(2)),
          ];
        }),
        // Aankopen + verkopen (verkochte beleggingen)
        ...(verkochteBeleggingen || []).flatMap(b => {
          const factor = getMuntFactor(b.munt || 'EUR');
          const rijen = [];
          if (b.datum) rijen.push([
            b.datum, 'Aankoop', b.naam || b.symbol, b.symbol, b.munt || 'EUR',
            b.aantalVerkocht || b.aantal, b.kostprijs, b.transactiekosten || 0,
            parseFloat((b.kostprijs * (b.aantalVerkocht || b.aantal) * factor + (b.transactiekosten || 0) * factor).toFixed(2)),
          ]);
          if (b.verkoopdatum) rijen.push([
            b.verkoopdatum, 'Verkoop', b.naam || b.symbol, b.symbol, b.munt || 'EUR',
            b.aantalVerkocht || b.aantal, b.verkoopkoers, 0,
            parseFloat((b.verkoopkoers * (b.aantalVerkocht || b.aantal) * factor).toFixed(2)),
          ]);
          return rijen;
        }),
      ].sort((a, b) => a[0] < b[0] ? -1 : 1); // Sorteren op datum

      const ws2 = XLSX.utils.aoa_to_sheet(transactieData);
      ws2['!cols'] = [12,10,28,10,8,8,10,14,12].map(w => ({ wch: w }));
      XLSX.utils.book_append_sheet(wb, ws2, 'Transacties');

      // Bestandsnaam zoals Saxo: Posities_17-jun-2026_1_03_05
      const maandNamen = ['jan','feb','mrt','apr','mei','jun','jul','aug','sep','okt','nov','dec'];
      const saxoDatum = `${nu.getDate()}-${maandNamen[nu.getMonth()]}-${nu.getFullYear()}`;
      const bestandsnaam = `Posities_${saxoDatum}_${tijdStr.replace(/_/g,'_')}.xlsx`;
      XLSX.writeFile(wb, bestandsnaam);
    });
  };


  const ColHeader = ({ children }) => (
    <span style={{ display: 'flex', alignItems: 'center', gap: 4, cursor: 'default', userSelect: 'none' }}>
      {children}
    </span>
  );

  return (
    <div style={{ padding: '0 0 60px' }}>
      {/* Page header */}
      <div className="page-header" style={{ marginBottom: 24 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
          <SidebarToggleKnop onToggleSidebar={onToggleSidebar} sidebarCollapsed={sidebarCollapsed} />
          <h1>{t('bel_titel')}</h1>
        </div>
        <div style={{ display: 'flex', gap: 10 }}>
          <button className="btn btn-secondary" onClick={exporteerNaarExcel} style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
            <Download size={15} /> {t('bel_exporteren')}
          </button>
          <button className="btn btn-primary" onClick={onToevoegen}>
            <Plus size={16} /> {t('ov_beleggingen_toevoegen')}
          </button>
        </div>
      </div>

      <div style={{ padding: '0 32px' }}>
        {/* Tabs */}
        <div style={{ display: 'flex', gap: 0, borderBottom: '1px solid var(--border)', marginBottom: 24 }}>
          {['actief', 'verkocht', 'geschiedenis'].map(tb => (
            <button key={tb} onClick={() => setTab(tb)} style={{
              padding: '10px 20px', border: 'none', background: 'transparent',
              fontFamily: 'inherit', fontSize: 14, fontWeight: 600,
              color: tab === tb ? 'var(--text-primary)' : 'var(--text-muted)',
              borderBottom: tab === tb ? '2px solid var(--accent)' : '2px solid transparent',
              cursor: 'pointer', textTransform: 'capitalize', marginBottom: -1
            }}>
              {tb === 'actief' ? t('bel_tab_actief') : tb === 'verkocht' ? t('bel_tab_verkocht') : t('bel_tab_geschiedenis')}
            </button>
          ))}
        </div>

        {/* ── ACTIEF TAB ── */}
        {tab === 'actief' && (
          <>
            {beleggingen.length === 0 ? (
              <div className="empty-state">
                <Plus size={40} />
                <h3>{t('bel_leeg_titel')}</h3>
                <p>{t('bel_leeg_tekst')}</p>
                <button className="btn btn-primary" style={{ marginTop: 16 }} onClick={onToevoegen}>
                  {t('bel_belegging_toevoegen')}
                </button>
              </div>
            ) : (
              <div className="card" style={{ padding: 0, overflow: 'hidden' }}>
                <div style={{ padding: '18px 24px 14px', borderBottom: '1px solid var(--border-light)' }}>
                  <div style={{ fontSize: 16, fontWeight: 700, marginBottom: 2 }}>{t('bel_titel')}</div>
                  <div style={{ fontSize: 13, color: 'var(--text-muted)' }}>{t('ov_automatisch_opgevolgd')}</div>
                </div>

                {/* Kolomhoofden */}
                <div className="belegging-table-header" style={{
                  display: 'grid',
                  gridTemplateColumns: '2.5fr 1.2fr 1.4fr 0.8fr 40px',
                  padding: '8px 24px',
                  borderBottom: '1px solid var(--border-light)',
                  fontSize: 12, fontWeight: 600, color: 'var(--text-muted)',
                  alignItems: 'center'
                }}>
                  {[['naam',t('ov_col_naam')],['datum',t('bel_col_aankoopdatum')],['kostprijs',t('bel_col_kostprijs')],['aantal',t('bel_col_aantal')]].map(([col,label]) => (
                    <span key={col} onClick={() => wisselSort(col)} style={{ cursor: 'pointer', userSelect: 'none', display: 'flex', alignItems: 'center', gap: 4 }}>
                      {label} <span style={{ color: sortCol === col ? 'var(--accent)' : 'var(--text-muted)' }}>{sortPijl(col)}</span>
                    </span>
                  ))}
                  <span />
                </div>

                {/* Rijen */}
                {gesorteerd(beleggingen).map((b) => {
                  const ms = muntSymbool(b.munt || 'EUR');
                  if (isMobiel) {
                    // Kaart: wat je wil zien (waarde en winst), details bij aantikken
                    const k = koersen[b.symbol];
                    const factor = getMuntFactor ? getMuntFactor(b.munt || 'EUR') : 1;
                    const waarde = (k ? k.c : b.kostprijs) * b.aantal * factor;
                    const inleg = kostEur ? kostEur(b) : (b.kostprijs * b.aantal + (b.transactiekosten || 0)) * factor;
                    const winst = waarde - inleg;
                    const winstPct = inleg > 0 ? (winst / inleg) * 100 : 0;
                    const kleur = winst >= 0 ? 'var(--green)' : 'var(--red)';
                    const datumTekst = b.datum ? new Date(b.datum).toLocaleDateString('nl-BE', { day: 'numeric', month: 'short', year: 'numeric' }) : null;
                    return (
                      <div key={b.id} onClick={() => setDetailBelegging(b)}
                        style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '12px 12px 12px 16px', borderBottom: '1px solid var(--border-light)', cursor: 'pointer' }}>
                        <Avatar symbol={b.symbol} logo={b.logo} naam={b.naam} type={b.type} />
                        <div style={{ flex: 1, minWidth: 0 }}>
                          <div style={{ fontWeight: 600, fontSize: 15, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{b.naam}</div>
                          <div style={{ fontSize: 12, color: 'var(--text-muted)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                            {b.aantal} st. · {ms}{koersFmt(b.kostprijs)}{datumTekst ? ` · ${datumTekst}` : ''}
                          </div>
                        </div>
                        <div style={{ textAlign: 'right', flexShrink: 0 }}>
                          <div style={{ fontWeight: 700, fontSize: 15, fontVariantNumeric: 'tabular-nums' }}>€{getal(waarde, 2)}</div>
                          <div style={{ fontSize: 12, fontWeight: 600, color: kleur, fontVariantNumeric: 'tabular-nums' }}>
                            {winst >= 0 ? '+' : '-'}€{getal(Math.abs(winst), 2)} · {winst >= 0 ? '+' : '-'}{getal(Math.abs(winstPct), 1)}%
                          </div>
                        </div>
                        <div onClick={e => e.stopPropagation()} style={{ flexShrink: 0 }}>
                          <KebabMenu
                            onDetail={() => setDetailBelegging(b)}
                            onVerkopen={() => openVerkoopModal(b)}
                            onVerwijder={() => verwijder(b.id)}
                          />
                        </div>
                      </div>
                    );
                  }
                  return (
                    <div key={b.id} className="belegging-row-grid" style={{
                      display: 'grid',
                      gridTemplateColumns: '2.5fr 1.2fr 1.4fr 0.8fr 40px',
                      padding: '14px 24px',
                      borderBottom: '1px solid var(--border-light)',
                      alignItems: 'center',
                      cursor: 'pointer',
                      transition: 'background 0.1s'
                    }}
                      onMouseEnter={e => e.currentTarget.style.background = 'var(--bg)'}
                      onMouseLeave={e => e.currentTarget.style.background = 'transparent'}
                      onClick={() => setDetailBelegging(b)}
                    >
                      {/* Naam */}
                      <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                        <Avatar symbol={b.symbol} logo={b.logo} naam={b.naam} type={b.type} />
                        <div>
                          <div style={{ fontWeight: 600, fontSize: 14 }}>{b.naam}</div>
                          <div style={{ fontSize: 12, color: 'var(--text-muted)' }}>{b.symbol}</div>
                        </div>
                      </div>

                      {/* Datum */}
                      <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                        <span style={{
                          padding: '5px 10px', border: '1px solid var(--border)',
                          borderRadius: 7, fontSize: 13, fontFamily: 'DM Mono, monospace',
                          background: 'var(--bg-white)', color: 'var(--text-primary)'
                        }}>
                          {b.datum || '—'}
                        </span>
                        <Calendar size={14} style={{ color: 'var(--text-muted)' }} />
                      </div>

                      {/* Kostprijs */}
                      <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                        <span style={{
                          flex: 1, padding: '5px 10px', border: '1px solid var(--border)',
                          borderRadius: 7, fontSize: 13, fontFamily: 'DM Mono, monospace',
                          background: 'var(--bg-white)', color: 'var(--text-primary)',
                          minWidth: 80
                        }}>
                          {koersFmt(b.kostprijs)}
                        </span>
                        <span style={{
                          padding: '5px 10px', border: '1px solid var(--border)', borderRadius: 7,
                          fontSize: 12, background: 'var(--bg)', color: 'var(--text-secondary)',
                          display: 'flex', alignItems: 'center', gap: 4, cursor: 'default'
                        }}>
                          {b.munt || 'EUR'} <ChevronDown size={12} />
                        </span>
                      </div>

                      {/* Aantal */}
                      <div>
                        <span style={{
                          padding: '5px 10px', border: '1px solid var(--border)',
                          borderRadius: 7, fontSize: 13, fontFamily: 'DM Mono, monospace',
                          background: 'var(--bg-white)', color: 'var(--text-primary)',
                          display: 'inline-block'
                        }}>
                          {b.aantal}
                        </span>
                      </div>

                      {/* Kebab menu */}
                      <div onClick={e => e.stopPropagation()}>
                        <KebabMenu
                          onDetail={() => setDetailBelegging(b)}
                          onVerkopen={() => openVerkoopModal(b)}
                          onVerwijder={() => verwijder(b.id)}
                        />
                      </div>
                    </div>
                  );
                })}

                {/* Opslaan knop (rechtsonder, zoals Plutu) */}
                <div style={{ padding: '12px 24px', display: 'flex', justifyContent: 'flex-end' }}>
                  <button
                    onClick={() => openVerkoopModal()}
                    style={{
                      padding: '9px 20px', background: 'var(--accent)', color: 'white',
                      border: 'none', borderRadius: 8, cursor: 'pointer',
                      fontFamily: 'inherit', fontSize: 14, fontWeight: 600
                    }}
                  >
                    {t('bel_verkoop_registreren')}
                  </button>
                </div>
              </div>
            )}
          </>
        )}

        {/* ── VERKOCHT TAB ── */}
        {tab === 'verkocht' && (
          <>
            <div style={{ display: 'flex', justifyContent: 'flex-end', marginBottom: 16 }}>
              <button
                onClick={() => openVerkoopModal()}
                style={{
                  display: 'flex', alignItems: 'center', gap: 6,
                  padding: '9px 16px', background: 'var(--accent)', color: 'white',
                  border: 'none', borderRadius: 8, cursor: 'pointer',
                  fontFamily: 'inherit', fontSize: 14, fontWeight: 600
                }}
              >
                <Plus size={15} /> {t('bel_verkoop_registreren')}
              </button>
            </div>

            {(!verkochteBeleggingen || verkochteBeleggingen.length === 0) ? (
              <div className="empty-state">
                <Trash2 size={40} />
                <h3>{t('bel_leeg_verkocht_titel')}</h3>
                <p>{t('bel_leeg_verkocht_tekst')}</p>
              </div>
            ) : (
              <div className="card" style={{ padding: 0, overflow: 'hidden' }}>
                <div style={{ padding: '18px 24px 14px', borderBottom: '1px solid var(--border-light)' }}>
                  <div style={{ fontSize: 16, fontWeight: 700, marginBottom: 2 }}>{t('bel_verkocht_titel')}</div>
                  <div style={{ fontSize: 13, color: 'var(--text-muted)' }}>{t('bel_afgeronde_posities')}</div>
                </div>

                {/* Kolomhoofden */}
                <div className="belegging-table-header" style={{
                  display: 'grid',
                  gridTemplateColumns: '2.5fr 1.2fr 1.2fr 1.2fr 1fr 40px',
                  padding: '8px 24px',
                  borderBottom: '1px solid var(--border-light)',
                  fontSize: 12, fontWeight: 600, color: 'var(--text-muted)',
                  alignItems: 'center'
                }}>
                  {[['naam',t('ov_col_naam')],['datum',t('bel_col_verkoopdatum')],['kostprijs',t('bel_col_aankoopkoers')],['verkoopkoers',t('bel_col_verkoopkoers')],['winst',t('bel_col_winst_verlies')]].map(([col,label]) => (
                    <span key={col} onClick={() => wisselSort(col)} style={{ cursor: 'pointer', userSelect: 'none', display: 'flex', alignItems: 'center', gap: 4 }}>
                      {label} <span style={{ color: sortCol === col ? 'var(--accent)' : 'var(--text-muted)' }}>{sortPijl(col)}</span>
                    </span>
                  ))}
                  <span />
                </div>

                {[...verkochteBeleggingen].sort((a, b) => {
                  let va, vb;
                  switch (sortCol) {
                    case 'naam': va = a.naam?.toLowerCase(); vb = b.naam?.toLowerCase(); break;
                    case 'kostprijs': va = a.kostprijs; vb = b.kostprijs; break;
                    case 'verkoopkoers': va = a.verkoopkoers || 0; vb = b.verkoopkoers || 0; break;
                    case 'winst': va = a.winstverlies || 0; vb = b.winstverlies || 0; break;
                    default: va = parseDatum(a.verkoopdatum || a.datum); vb = parseDatum(b.verkoopdatum || b.datum);
                  }
                  if (va < vb) return sortDir === 'asc' ? -1 : 1;
                  if (va > vb) return sortDir === 'asc' ? 1 : -1;
                  return 0;
                }).map((b) => {
                  const wv = b.winstverlies || 0;
                  const isPos = wv >= 0;
                  const ms = muntSymbool(b.verkoopMunt || b.munt || 'EUR');
                  const verwijderVerkoop = () => {
                    if (window.confirm(t('bel_verkoop_verwijderen_confirm'))) {
                      setVerkochteBeleggingen(prev => prev.filter((_, i) => prev[i] !== b));
                    }
                  };
                  if (isMobiel) {
                    const vd = b.verkoopdatum ? new Date(parseDatum(b.verkoopdatum)) : null;
                    const vdTekst = vd && !isNaN(vd) ? vd.toLocaleDateString('nl-BE', { day: 'numeric', month: 'short', year: 'numeric' }) : (b.verkoopdatum || '');
                    return (
                      <div key={b.id + b.verkoopdatum} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '12px 12px 12px 16px', borderBottom: '1px solid var(--border-light)' }}>
                        <Avatar symbol={b.symbol} logo={b.logo} naam={b.naam} type={b.type} />
                        <div style={{ flex: 1, minWidth: 0 }}>
                          <div style={{ fontWeight: 600, fontSize: 15, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{b.naam}</div>
                          <div style={{ fontSize: 12, color: 'var(--text-muted)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                            {b.aantalVerkocht || b.aantal} st. · {muntSymbool(b.munt || 'EUR')}{koersFmt(b.kostprijs)} → {b.verkoopkoers != null ? ms + koersFmt(b.verkoopkoers) : '—'}
                          </div>
                          <div style={{ fontSize: 12, color: 'var(--text-muted)' }}>Verkocht op {vdTekst}</div>
                        </div>
                        <div style={{ textAlign: 'right', flexShrink: 0, fontWeight: 700, fontSize: 15, color: isPos ? 'var(--green)' : 'var(--red)', fontVariantNumeric: 'tabular-nums' }}>
                          {isPos ? '+' : '-'}{ms}{getal(Math.abs(wv), 2)}
                        </div>
                        <button onClick={verwijderVerkoop} aria-label="Verkoop verwijderen"
                          style={{ background: 'transparent', border: 'none', cursor: 'pointer', color: 'var(--text-muted)', padding: 6, borderRadius: 6, flexShrink: 0 }}>
                          <Trash2 size={15} />
                        </button>
                      </div>
                    );
                  }
                  return (
                    <div key={b.id + b.verkoopdatum} className="belegging-row-grid" style={{
                      display: 'grid',
                      gridTemplateColumns: '2.5fr 1.2fr 1.2fr 1.2fr 1fr 40px',
                      padding: '14px 24px',
                      borderBottom: '1px solid var(--border-light)',
                      alignItems: 'center'
                    }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                        <Avatar symbol={b.symbol} logo={b.logo} naam={b.naam} type={b.type} />
                        <div>
                          <div style={{ fontWeight: 600, fontSize: 14 }}>{b.naam}</div>
                          <div style={{ fontSize: 12, color: 'var(--text-muted)' }}>{b.symbol}</div>
                        </div>
                      </div>
                      <div style={{ fontSize: 13, fontFamily: 'DM Mono, monospace' }}>{b.verkoopdatum}</div>
                      <div style={{ fontSize: 13, fontFamily: 'DM Mono, monospace' }}>
                        {muntSymbool(b.munt || 'EUR')}{koersFmt(b.kostprijs)}
                      </div>
                      <div style={{ fontSize: 13, fontFamily: 'DM Mono, monospace' }}>
                        {b.verkoopkoers != null ? ms + koersFmt(b.verkoopkoers) : '—'}
                      </div>
                      <div style={{
                        fontSize: 13, fontFamily: 'DM Mono, monospace', fontWeight: 600,
                        color: isPos ? 'var(--green)' : 'var(--red)'
                      }}>
                        {isPos ? '+' : '-'}{ms}{getal(Math.abs(wv), 2)}
                      </div>
                      <button
                        onClick={() => {
                          if (window.confirm(t('bel_verkoop_verwijderen_confirm'))) {
                            setVerkochteBeleggingen(prev => prev.filter((_, i) => prev[i] !== b));
                          }
                        }}
                        style={{ background: 'transparent', border: 'none', cursor: 'pointer',
                          color: 'var(--text-muted)', padding: '4px 6px', borderRadius: 6 }}>
                        <Trash2 size={14} />
                      </button>
                    </div>
                  );
                })}
              </div>
            )}
          </>
        )}

        {/* ── GESCHIEDENIS TAB ── */}
        {tab === 'geschiedenis' && (() => {
          const MAAND_NAMEN = {
            nl: ['jan','feb','mrt','apr','mei','jun','jul','aug','sep','okt','nov','dec'],
            en: ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'],
            fr: ['janv.','févr.','mars','avr.','mai','juin','juil.','août','sept.','oct.','nov.','déc.'],
          };
          const maandNamen = MAAND_NAMEN[gebruiker.taal] || MAAND_NAMEN.nl;
          const formatDatum = (s) => {
            if (!s) return '—';
            const d = new Date(s);
            return isNaN(d) ? s : `${d.getDate()} ${maandNamen[d.getMonth()]} ${d.getFullYear()}`;
          };

          const transacties = [
            ...beleggingen.map(b => ({
              datum: b.datum || '', type: 'aankoop',
              naam: b.naam || b.symbol, symbol: b.symbol, logo: b.logo,
              munt: b.munt || 'EUR', aantal: b.aantal,
              koers: b.kostprijs, kosten: b.transactiekosten || 0,
              id: `buy_${b.id}`,
            })),
            ...(verkochteBeleggingen || []).flatMap(b => {
              const items = [];
              if (b.datum) items.push({ datum: b.datum, type: 'aankoop', naam: b.naam || b.symbol, symbol: b.symbol, logo: b.logo, munt: b.munt || 'EUR', aantal: b.aantalVerkocht || b.aantal, koers: b.kostprijs, kosten: b.transactiekosten || 0, id: `buy_v_${b.id}` });
              if (b.verkoopdatum) items.push({ datum: b.verkoopdatum, type: 'verkoop', naam: b.naam || b.symbol, symbol: b.symbol, logo: b.logo, munt: b.munt || 'EUR', aantal: b.aantalVerkocht || b.aantal, koers: b.verkoopkoers, kosten: 0, winstverlies: b.winstverlies, id: `sell_${b.id}` });
              return items;
            }),
          ].sort((a, b) => (b.datum || '') > (a.datum || '') ? 1 : -1);

          if (transacties.length === 0) return (
            <div className="empty-state"><h3>{t('bel_leeg_transacties_titel')}</h3><p>{t('bel_leeg_tekst')}</p></div>
          );

          return (
            <div className="card" style={{ padding: 0, overflow: 'hidden' }}>
              <div style={{ padding: '16px 24px', borderBottom: '1px solid var(--border-light)' }}>
                <div style={{ fontWeight: 700, fontSize: 15 }}>{t('bel_transactiegeschiedenis')}</div>
                <div style={{ fontSize: 12, color: 'var(--text-muted)', marginTop: 2 }}>{transacties.length} {t('bel_transacties_suffix')}</div>
              </div>
              {!isMobiel && <div style={{ display: 'grid', gridTemplateColumns: '1.5fr 100px 1fr 1fr 1fr 1fr', padding: '10px 24px', background: 'var(--bg-subtle)', borderBottom: '1px solid var(--border-light)', fontSize: 11, fontWeight: 700, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                <span>{t('bel_col_instrument')}</span><span>{t('bel_col_type')}</span><span>{t('bel_col_datum')}</span>
                <span style={{ textAlign: 'right' }}>{t('bel_col_aantal')}</span>
                <span style={{ textAlign: 'right' }}>{t('ov_col_koers')}</span>
                <span style={{ textAlign: 'right' }}>{t('ov_totaal')}</span>
              </div>}
              {transacties.map((tx, idx) => {
                const factor = getMuntFactor ? getMuntFactor(tx.munt) : (tx.munt === 'USD' ? 0.865 : 1);
                const totaal = (tx.koers || 0) * tx.aantal * factor + (tx.kosten || 0);
                const ms = muntSymbool(tx.munt);
                const isAankoop = tx.type === 'aankoop';
                if (isMobiel) {
                  return (
                    <div key={tx.id} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '12px 16px', borderBottom: idx < transacties.length - 1 ? '1px solid var(--border-light)' : 'none' }}>
                      <Avatar symbol={tx.symbol} logo={tx.logo} naam={tx.naam} />
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <div style={{ fontWeight: 600, fontSize: 15, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{tx.naam}</div>
                        <div style={{ fontSize: 12, color: 'var(--text-muted)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                          <span style={{ fontWeight: 700, color: isAankoop ? 'var(--green)' : 'var(--red)' }}>{isAankoop ? `↑ ${t('ov_tooltip_aankoop')}` : `↓ ${t('ov_tooltip_verkoop')}`}</span>
                          {' · '}{formatDatum(tx.datum)}
                        </div>
                        <div style={{ fontSize: 12, color: 'var(--text-muted)' }}>{tx.aantal} × {ms}{koersFmt(tx.koers || 0)}</div>
                      </div>
                      <div style={{ textAlign: 'right', flexShrink: 0, fontWeight: 700, fontSize: 15, color: isAankoop ? 'var(--text-primary)' : 'var(--green)', fontVariantNumeric: 'tabular-nums' }}>
                        {isAankoop ? '-' : '+'}€{getal(Math.abs(totaal), 2)}
                      </div>
                    </div>
                  );
                }
                return (
                  <div key={tx.id} style={{ display: 'grid', gridTemplateColumns: '1.5fr 100px 1fr 1fr 1fr 1fr', padding: '14px 24px', borderBottom: idx < transacties.length - 1 ? '1px solid var(--border-light)' : 'none', alignItems: 'center' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                      <Avatar symbol={tx.symbol} logo={tx.logo} />
                      <div>
                        <div style={{ fontWeight: 600, fontSize: 14 }}>{tx.naam}</div>
                        <div style={{ fontSize: 11, color: 'var(--text-muted)', fontFamily: 'monospace' }}>{tx.symbol}</div>
                      </div>
                    </div>
                    <div>
                      <span style={{ fontSize: 11, fontWeight: 700, padding: '3px 8px', borderRadius: 6, background: isAankoop ? 'var(--green-bg)' : 'var(--red-bg)', color: isAankoop ? 'var(--green)' : 'var(--red)' }}>
                        {isAankoop ? `↑ ${t('ov_tooltip_aankoop')}` : `↓ ${t('ov_tooltip_verkoop')}`}
                      </span>
                    </div>
                    <div style={{ fontSize: 13, color: 'var(--text-muted)' }}>{formatDatum(tx.datum)}</div>
                    <div style={{ fontSize: 13, fontFamily: 'monospace', textAlign: 'right' }}>{tx.aantal}</div>
                    <div style={{ fontSize: 13, fontFamily: 'monospace', textAlign: 'right' }}>{ms}{koersFmt(tx.koers || 0)}</div>
                    <div style={{ fontSize: 13, fontFamily: 'monospace', textAlign: 'right', fontWeight: 600, color: isAankoop ? 'var(--text-primary)' : 'var(--green)' }}>
                      {isAankoop ? '-' : '+'}€{getal(Math.abs(totaal), 2)}
                    </div>
                  </div>
                );
              })}
            </div>
          );
        })()}
      </div>

      {/* Modals */}
      {verkoopModal && (
        <VerkoopModal
          beleggingen={verkoopVoorBelegging ? [verkoopVoorBelegging] : beleggingen}
          koersen={koersen}
          onClose={() => { setVerkoopModal(false); setVerkoopVoorBelegging(null); }}
          onBevestig={registreerVerkoop}
        />
      )}
      {detailBelegging && (
        <BeleggingDetail belegging={detailBelegging} onClose={() => setDetailBelegging(null)} />
      )}
    </div>
  );
}
