import React, { useState, useEffect, useMemo } from 'react';
import { EffectLogoKlein } from '../components/EffectLogo';
import { useApp } from '../context/AppContext';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import { Info, X } from 'lucide-react';
import SidebarToggleKnop from '../components/SidebarToggleKnop';

import { getal } from '../utils/getal';
import { naarIsoDatum } from '../utils/handelsdag';
import { bronheffing, procent } from '../utils/dividendbelasting';
const ACCENT = '#1e3a8a';
const fmt2 = (v) => v.toLocaleString('nl-BE', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

// ── Dividend database (bruto, per aandeel, jaarlijks) ──────────────
// Bron: meest recente uitkering × frequentie
const DIVIDEND_DB = {
  // Aandelen
  // Bijgewerkt juni 2026 op basis van actuele uitkeringen
  NVDA: { jaarlijks: 1.00, frequentie: 4, ex_maanden: [3, 6, 9, 12] },      // $0.25/kwartaal (verhoogd in 2026)
  MSFT: { jaarlijks: 3.32, frequentie: 4, ex_maanden: [2, 5, 8, 11] },      // $0.83/kwartaal
  AAPL: { jaarlijks: 1.00, frequentie: 4, ex_maanden: [2, 5, 8, 11] },      // $0.25/kwartaal
  AMZN: { jaarlijks: 0, frequentie: 0, ex_maanden: [] },
  GOOGL: { jaarlijks: 0.80, frequentie: 4, ex_maanden: [3, 6, 9, 12] },     // $0.20/kwartaal
  META: { jaarlijks: 2.00, frequentie: 4, ex_maanden: [3, 6, 9, 12] },      // $0.50/kwartaal
  TSLA: { jaarlijks: 0, frequentie: 0, ex_maanden: [] },
  JPM: { jaarlijks: 4.60, frequentie: 4, ex_maanden: [1, 4, 7, 10] },       // $1.15/kwartaal
  V: { jaarlijks: 2.08, frequentie: 4, ex_maanden: [2, 5, 8, 11] },         // $0.52/kwartaal
  MA: { jaarlijks: 2.64, frequentie: 4, ex_maanden: [1, 4, 7, 10] },        // $0.66/kwartaal
  JNJ: { jaarlijks: 4.96, frequentie: 4, ex_maanden: [2, 5, 8, 11] },       // $1.24/kwartaal
  NKE: { jaarlijks: 1.64, frequentie: 4, ex_maanden: [3, 6, 9, 12] },       // $0.41/kwartaal (bijgewerkt jun 2026)
  SOFI: { jaarlijks: 0, frequentie: 0, ex_maanden: [], geenDividend: true },
  PRX: { jaarlijks: 0.20, frequentie: 1, ex_maanden: [10] },    // €0.20/jaar, ex-datum oktober
  AVGO: { jaarlijks: 21.00, frequentie: 4, ex_maanden: [2, 5, 8, 11] },     // $5.25/kwartaal
  // ETFs — accumulerend (geen dividend)
  VWCE: { jaarlijks: 0, frequentie: 0, ex_maanden: [], accumulating: true },
  VWRL: { jaarlijks: 1.20, frequentie: 4, ex_maanden: [3, 6, 9, 12] },
  IWDA: { jaarlijks: 0, frequentie: 0, ex_maanden: [], accumulating: true },
  SWRD: { jaarlijks: 0, frequentie: 0, ex_maanden: [], accumulating: true },
  EMIM: { jaarlijks: 0, frequentie: 0, ex_maanden: [], accumulating: true },
  CSPX: { jaarlijks: 0, frequentie: 0, ex_maanden: [], accumulating: true },
  SXR8: { jaarlijks: 0, frequentie: 0, ex_maanden: [], accumulating: true },
  EQQQ: { jaarlijks: 0, frequentie: 0, ex_maanden: [], accumulating: true },
  XDWD: { jaarlijks: 0, frequentie: 0, ex_maanden: [], accumulating: true },
  LCWD: { jaarlijks: 0, frequentie: 0, ex_maanden: [], accumulating: true },
  WEBG: { jaarlijks: 0, frequentie: 0, ex_maanden: [], accumulating: true },
};

// Historische jaarlijkse dividenden per aandeel (USD) voor nauwkeurige berekening
const DIVIDEND_HISTORIEK = {
  NVDA: {
    2022: { jaarlijks: 0.016, frequentie: 4, ex_maanden: [3, 6, 9, 12] },
    2023: { jaarlijks: 0.016, frequentie: 4, ex_maanden: [3, 6, 9, 12] },
    2024: { jaarlijks: 0.04, frequentie: 4, ex_maanden: [3, 6, 9, 12] },
    2025: { jaarlijks: 0.04, frequentie: 4, ex_maanden: [3, 6, 9, 12] },  // 4x$0.01
    2026: { jaarlijks: 1.00, frequentie: 4, ex_maanden: [3, 6, 9, 12] },  // verhoogd naar $0.25/kwartaal
  },
  NKE: {
    2022: { jaarlijks: 1.36, frequentie: 4, ex_maanden: [1, 4, 7, 10] },
    2023: { jaarlijks: 1.48, frequentie: 4, ex_maanden: [1, 4, 7, 10] },
    2024: { jaarlijks: 1.54, frequentie: 4, ex_maanden: [1, 4, 7, 10] },
    2025: { jaarlijks: 1.57, frequentie: 4, ex_maanden: [1, 4, 7, 10] },  // jan$0.37 + apr/jul/okt$0.40
    2026: { jaarlijks: 1.64, frequentie: 4, ex_maanden: [1, 4, 7, 10] },  // 4x$0.41
  },
  MSFT: {
    2022: { jaarlijks: 2.48, frequentie: 4, ex_maanden: [2, 5, 8, 11] },
    2023: { jaarlijks: 2.72, frequentie: 4, ex_maanden: [2, 5, 8, 11] },
    2024: { jaarlijks: 3.00, frequentie: 4, ex_maanden: [2, 5, 8, 11] },
    2025: { jaarlijks: 3.32, frequentie: 4, ex_maanden: [2, 5, 8, 11] },  // $0.83/kwartaal heel 2025
    2026: { jaarlijks: 3.64, frequentie: 4, ex_maanden: [2, 5, 8, 11] },  // $0.91/kwartaal
  },
};

const getDividendData = (symbol, jaar) => {
  const basis = symbol.toUpperCase().split('.')[0];
  // Gebruik jaar-specifieke data als beschikbaar
  if (jaar && DIVIDEND_HISTORIEK[basis]?.[jaar]) {
    return DIVIDEND_HISTORIEK[basis][jaar];
  }
  return DIVIDEND_DB[basis] || null;
};

// Roerende voorheffing België = 30%
const BELASTING = 0.30;

const MAANDEN = ['jan', 'feb', 'mrt', 'apr', 'mei', 'jun', 'jul', 'aug', 'sep', 'okt', 'nov', 'dec'];

export default function Dividend({ sidebarCollapsed, onToggleSidebar }) {
  const { beleggingen, koersen, getMuntFactor, fxOp, verkochteBeleggingen, profielInfo } = useApp();
  const [jaar, setJaar] = useState(new Date().getFullYear());
  const [modus, setModus] = useState('bruto'); // 'bruto' | 'netto'
  const [jaarDropdown, setJaarDropdown] = useState(false);
  const [rendementInfo, setRendementInfo] = useState(false);
  const [dividendInfo, setDividendInfo] = useState(false);
  const [liveDividend, setLiveDividend] = useState({}); // { NVDA: { jaarlijks, ontvangen } }

  const factor = (b) => getMuntFactor ? getMuntFactor(b.munt || 'EUR') : ((b.munt || 'EUR') === 'USD' ? 0.865 : 1);

  // Verwijder oude cache met verkeerd formaat bij eerste load
  useEffect(() => {
    const sleutels = Object.keys(localStorage).filter(k => k.startsWith('matico_div_'));
    sleutels.forEach(k => {
      try {
        const cached = JSON.parse(localStorage.getItem(k));
        // Oude cache had geen genormaliseerd formaat (geen exDate veld)
        if (cached?.data?.[0] && !cached.data[0].exDate && cached.data[0].date) {
          localStorage.removeItem(k); // Verwijder verouderd formaat
        }
      } catch (e) {}
    });
  }, []);

  // Haal live dividenddata op via Finnhub — per symbool én per jaar
  // Sleutel: "NVDA_2025", "NKE_2024", ... zodat historische data bewaard blijft
  useEffect(() => {
    const alleBeleggingen = [
      ...beleggingen,
      ...(verkochteBeleggingen || [])
    ];
    const symbolen = [...new Set(alleBeleggingen.map(b => b.symbol))];

    symbolen.forEach(async (sym) => {
      const basis = sym.toUpperCase().split('.')[0];
      const sleutel = `${basis}_${jaar}`;
      const cacheKey = `matico_div_${sleutel}`;

      // Check cache — historische jaren cachen langer (1 jaar), huidig jaar 7 dagen
      const huidigJaar = new Date().getFullYear();
      const cacheDuur = jaar < huidigJaar
        ? 365 * 24 * 60 * 60 * 1000  // historisch: 1 jaar
        : 7 * 24 * 60 * 60 * 1000;   // huidig jaar: 7 dagen

      try {
        const cached = localStorage.getItem(cacheKey);
        if (cached) {
          const { data, timestamp } = JSON.parse(cached);
          // Een leeg antwoord kan een tijdelijke fout zijn: maximaal 6 uur bewaren
          const duur = Array.isArray(data) && data.length === 0 ? Math.min(cacheDuur, 6 * 60 * 60 * 1000) : cacheDuur;
          if (Date.now() - timestamp < duur) {
            setLiveDividend(prev => ({ ...prev, [sleutel]: data }));
            return;
          }
        }
      } catch (e) {}

      try {
        const van = `${jaar}-01-01`;
        const tot = `${jaar}-12-31`;
        const res = await fetch(`/api/data?endpoint=dividend&symbol=${sym}&van=${van}&tot=${tot}`);
        const data = await res.json();
        if (data && Array.isArray(data) && data.length > 0) {
          localStorage.setItem(cacheKey, JSON.stringify({ data, timestamp: Date.now() }));
          setLiveDividend(prev => ({ ...prev, [sleutel]: data }));
        } else {
          // Geen data van Finnhub — markeer als gecontroleerd zodat we niet blijven proberen
          localStorage.setItem(cacheKey, JSON.stringify({ data: [], timestamp: Date.now() }));
        }
      } catch (e) {}
    });
  }, [beleggingen.map(b => b.symbol).join(','), (verkochteBeleggingen || []).map(b => b.symbol).join(','), jaar]);

  // ── Bereken dividenddata per belegging ──
  // Gebruikt live Finnhub data als beschikbaar, anders hardcoded database
  const { perBelegging, ontvangen, geschat, uitsplitsing, verwacht, dividendRendement, rendementOpAankoop, maandData, zonderData, geenDividend } = useMemo(() => {
    const huidigMaand = new Date().getMonth() + 1;
    const huidigJaar = new Date().getFullYear();
    const isHuidigJaar = jaar === huidigJaar;

    const perBel = [];
    let totaalOntvangen = 0;
    let totaalVerwacht = 0;
    let totaalGeschat = 0;
    let totBruto = 0, totBron = 0; // ontvangen, voor de uitsplitsing bruto → netto // 'ontvangen' op basis van de vaste schattingslijst (geen brondata)
    const maandTotalen = Array(12).fill(0);
    const zonderDataLijst = [];
    const geenDividendLijst = []; // bedrijven die bewust geen dividend uitkeren

    const parseNLDatumHelper = (str) => {
      if (!str) return null;
      const d = str.split('/');
      return d.length === 3 ? new Date(`${d[2]}-${d[1]}-${d[0]}`) : new Date(str);
    };

    // Voeg verkochte beleggingen toe als ze in het gevraagde jaar nog bezit waren
    // (aankoop vóór eind van het jaar EN verkoop op/na begin van het jaar)
    const verkochtInOfNaJaar = (verkochteBeleggingen || []).filter(b => {
      const aankoopJ = b.datum ? new Date(b.datum).getFullYear() : 9999;
      const verkoopD = parseNLDatumHelper(b.verkoopdatum);
      const verkoopJ = verkoopD ? verkoopD.getFullYear() : 0;
      // Bezit overlapt met het gevraagde jaar als: aankoop <= eind jaar EN verkoop >= begin jaar
      return aankoopJ <= jaar && verkoopJ >= jaar;
    }).map(b => ({ ...b, aantal: b.aantalVerkocht }));

    const alleBel = [
      ...beleggingen,
      ...verkochtInOfNaJaar
    ];

    alleBel.forEach(b => {
      const basis = b.symbol.toUpperCase().split('.')[0];
      // Netto = bruto − buitenlandse bronheffing − 30% Belgische RV op de rest
      const bh = bronheffing(b.symbol, b.type, profielInfo?.[b.symbol]);
      const nf = (1 - bh.tarief) * (1 - BELASTING);
      const f = factor(b);
      const k = koersen[b.symbol];
      const huidigePrijs = k ? k.c : b.kostprijs;


      // Controleer of je recht hebt op dividend op een gegeven ex-datum
      // (zelfde regels als de grafiek in Overzicht, zie AppContext.dividendUitkeringen)
      const aankoopIso = naarIsoDatum(b.datum);
      const verkoopIso = naarIsoDatum(b.verkoopdatum);
      const heeftRecht = (exDatumStr) => {
        const ex = naarIsoDatum(exDatumStr);
        if (!ex) return false;
        // Je moet het aandeel bezitten VÓÓR de ex-dividenddatum: wie op de
        // ex-datum zelf koopt, heeft geen recht meer.
        if (aankoopIso && ex <= aankoopIso) return false;
        // Verkocht vóór de ex-datum: geen recht (op de ex-datum zelf wel)
        if (verkoopIso && ex > verkoopIso) return false;
        return true;
      };

      // ── Probeer live Finnhub data ──
      const liveData = liveDividend[`${basis}_${jaar}`];
      if (liveData && Array.isArray(liveData) && liveData.length > 0) {
        // Filter op het gevraagde jaar én op bezitperiode
        const uitkeringenDitJaar = liveData.filter(d => {
          const exDatumStr = d.exDate || d.date || d.ex_dividend_date || '';
          const exDatum = new Date(exDatumStr);
          if (isNaN(exDatum.getTime()) || exDatum.getFullYear() !== jaar) return false;
          return heeftRecht(exDatumStr);
        });

        // Alle uitkeringen dit jaar (voor rendementberekening, ook toekomstige)
        const alleUitkeringenJaar = liveData.filter(d => {
          const exDatumStr = d.exDate || d.date || d.ex_dividend_date || '';
          const exDatum = new Date(exDatumStr);
          return !isNaN(exDatum.getTime()) && exDatum.getFullYear() === jaar;
        });

        if (alleUitkeringenJaar.length > 0) {
          // Verwacht jaarlijks: gebaseerd op recentste bedrag × frequentie
          const recentsteUitkering = parseFloat(alleUitkeringenJaar[0]?.amount || alleUitkeringenJaar[0]?.adjDividend || 0);
          const frequentie = alleUitkeringenJaar.length <= 1 ? 4 : alleUitkeringenJaar.length;
          const jaarlijksUSD = recentsteUitkering * frequentie;

          // Verwacht voor bezitperiode: enkel uitkeringen waarvoor je recht hebt
          const verwachtUSD = uitkeringenDitJaar.reduce((s, d) =>
            s + parseFloat(d.amount || d.adjDividend || d.adj_dividend || 0), 0);
          // Als er nog toekomstige uitkeringen zijn waarvoor je recht zult hebben, tel ook mee
          const toekomstigeUSD = liveData.filter(d => {
            const exDatum = new Date(d.exDate || d.date || '');
            return exDatum.getFullYear() === jaar && heeftRecht(d.exDate || d.date);
          }).reduce((s, d) => s + parseFloat(d.amount || d.adjDividend || 0), 0);

          const verwachtBruto = toekomstigeUSD * b.aantal * f;
          const verwachtNetto = verwachtBruto * nf;

          // Ontvangen = uitkeringen waarvoor je recht had én al betaald
          // Omgerekend aan de wisselkoers van de betaaldag (zoals de grafiek)
          const fxBetaal = (d) => fxOp ? fxOp(d.currency || b.munt || 'EUR', d.paymentDate || d.payment_date || d.exDate || d.date) : f;
          const ontvangenBruto = uitkeringenDitJaar
            .filter(d => {
              const betaalDatumStr = d.paymentDate || d.payment_date || d.date || '';
              const betaalDatum = new Date(betaalDatumStr);
              return !isHuidigJaar || (!isNaN(betaalDatum.getTime()) && betaalDatum <= new Date());
            })
            .reduce((s, d) => s + parseFloat(d.amount || d.adjDividend || 0) * b.aantal * fxBetaal(d), 0);
          const ontvangenNetto = ontvangenBruto * nf;

          // Maanddata — enkel uitkeringen waarvoor je recht had
          uitkeringenDitJaar.forEach(d => {
            const betaalDatum = new Date(d.paymentDate || d.date || '');
            const maandIdx = betaalDatum.getMonth();
            if (!isHuidigJaar || betaalDatum <= new Date()) {
              const bedrag = parseFloat(d.amount || d.adjDividend || 0) * b.aantal * fxBetaal(d);
              maandTotalen[maandIdx] += modus === 'netto' ? bedrag * nf : bedrag;
            }
          });

          const rendement = huidigePrijs > 0 ? (jaarlijksUSD / huidigePrijs) * 100 : 0;
          const rendementAankoop = b.kostprijs > 0 ? (jaarlijksUSD / b.kostprijs) * 100 : 0;

          totaalOntvangen += modus === 'netto' ? ontvangenNetto : ontvangenBruto;
          totaalVerwacht += modus === 'netto' ? verwachtNetto : verwachtBruto;
          totBruto += ontvangenBruto; totBron += ontvangenBruto * bh.tarief;

          perBel.push({
            id: b.id || b.symbol, naam: b.naam, symbol: b.symbol, logo: b.logo,
            aantal: b.aantal, liveData: true, bronheffing: bh,
            verkocht: !beleggingen.find(bb => bb.symbol === b.symbol),
            rendement, rendementAankoop,
            verwachtJaarlijks: modus === 'netto' ? verwachtNetto : verwachtBruto,
            ontvangen: modus === 'netto' ? ontvangenNetto : ontvangenBruto,
          });
          return;
        }
      }

      // ── Fallback: hardcoded database ──
      const db = getDividendData(b.symbol, jaar);
      if (!db || db.jaarlijks === 0) {
        if (!db?.accumulating) {
          // Slim bepalen: heeft dit aandeel historisch ooit dividend uitgekeerd?
          // Check cache van de laatste 3 jaar
          const basis2 = b.symbol.toUpperCase().split('.')[0];
          let heeftHistorischDividend = false;
          let verwachteMaand = null;

          for (let y = jaar - 1; y >= jaar - 3; y--) {
            try {
              const cached = localStorage.getItem(`matico_div_${basis2}_${y}`);
              if (cached) {
                const { data } = JSON.parse(cached);
                if (data && data.length > 0) {
                  heeftHistorischDividend = true;
                  // Bepaal typische uitbetalingsmaand uit historische data
                  const maanden = data.map(d => new Date(d.exDate || d.date || '').getMonth() + 1).filter(m => m > 0);
                  if (maanden.length > 0) verwachteMaand = maanden[maanden.length - 1]; // meest recente
                  break;
                }
              }
            } catch (e) {}
          }

          if (db?.geenDividend) {
            geenDividendLijst.push(b.naam || b.symbol);
          } else if (heeftHistorischDividend && verwachteMaand) {
            const maandNamen = ['jan','feb','mrt','apr','mei','jun','jul','aug','sep','okt','nov','dec'];
            zonderDataLijst.push(`${b.naam || b.symbol} (verwacht ~${maandNamen[verwachteMaand - 1]})`);
          } else if (heeftHistorischDividend) {
            zonderDataLijst.push(`${b.naam || b.symbol} (verwacht later dit jaar)`);
          } else {
            geenDividendLijst.push(b.naam || b.symbol);
          }
        }
        return;
      }

      const uitkeringPerKeer = (db.jaarlijks / (db.frequentie || 1)) * b.aantal * f;
      let ontvangenBruto = 0;
      let verwachtBruto = 0;

      db.ex_maanden.forEach(m => {
        // Bouw een datum voor deze ex-dividendmaand in het gevraagde jaar
        const exDatumStr = `${jaar}-${String(m).padStart(2, '0')}-15`;
        if (!heeftRecht(exDatumStr)) return; // Geen recht (voor aankoop of na verkoop)

        const isAlBetaald = !isHuidigJaar || m <= huidigMaand;
        verwachtBruto += uitkeringPerKeer;
        if (isAlBetaald) {
          ontvangenBruto += uitkeringPerKeer;
          const maandIdx = Math.min(m, 12) - 1;
          if (maandIdx >= 0) maandTotalen[maandIdx] += modus === 'netto'
            ? uitkeringPerKeer * nf : uitkeringPerKeer;
        }
      });

      const ontvangenNetto = ontvangenBruto * nf;
      const verwachtNetto = verwachtBruto * nf;
      const rendement = huidigePrijs > 0 ? (db.jaarlijks / huidigePrijs) * 100 : 0;
      const rendementAankoop = b.kostprijs > 0 ? (db.jaarlijks / b.kostprijs) * 100 : 0;

      if (verwachtBruto === 0 && ontvangenBruto === 0) return; // Geen enkel dividend ontvangen/verwacht

      totaalOntvangen += modus === 'netto' ? ontvangenNetto : ontvangenBruto;
      totaalVerwacht += modus === 'netto' ? verwachtNetto : verwachtBruto;
      totaalGeschat += modus === 'netto' ? ontvangenNetto : ontvangenBruto;
      totBruto += ontvangenBruto; totBron += ontvangenBruto * bh.tarief;

      perBel.push({
        id: b.id || b.symbol, naam: b.naam, symbol: b.symbol, logo: b.logo,
        aantal: b.aantal, liveData: false, geschat: true, bronheffing: bh,
        verkocht: !beleggingen.find(bb => bb.symbol === b.symbol),
        rendement, rendementAankoop,
        verwachtJaarlijks: modus === 'netto' ? verwachtNetto : verwachtBruto,
        ontvangen: modus === 'netto' ? ontvangenNetto : ontvangenBruto,
        frequentie: db.frequentie,
      });
    });

    // Totaal rendement
    const totaalWaarde = beleggingen.reduce((s, b) => {
      const k = koersen[b.symbol]; return s + (k ? k.c : b.kostprijs) * b.aantal * factor(b);
    }, 0) || 1;
    const totaalKostprijs = beleggingen.reduce((s, b) => s + b.kostprijs * b.aantal * factor(b), 0) || 1;
    const jaarlijksBrutoTotaal = perBel.reduce((s, p) => s + p.verwachtJaarlijks, 0);

    return {
      perBelegging: perBel.sort((a, b) => b.ontvangen - a.ontvangen),
      ontvangen: totaalOntvangen,
      geschat: totaalGeschat,
      uitsplitsing: { bruto: totBruto, bron: totBron, rv: (totBruto - totBron) * BELASTING, netto: (totBruto - totBron) * (1 - BELASTING) },
      verwacht: totaalVerwacht,
      dividendRendement: (jaarlijksBrutoTotaal / totaalWaarde) * 100,
      rendementOpAankoop: (jaarlijksBrutoTotaal / totaalKostprijs) * 100,
      maandData: MAANDEN.map((label, i) => ({ label, waarde: maandTotalen[i] })),
      zonderData: [...new Set(zonderDataLijst)],
      geenDividend: [...new Set(geenDividendLijst)],
    };
  }, [beleggingen, koersen, jaar, modus, verkochteBeleggingen, liveDividend, getMuntFactor, fxOp, profielInfo]);

  const beschikbareJaren = useMemo(() => {
    const huidig = new Date().getFullYear();
    const alleDatums = [
      ...beleggingen.map(b => b.datum),
      ...(verkochteBeleggingen || []).map(b => b.datum)
    ].filter(Boolean);
    const vroegste = alleDatums.reduce((min, datum) => {
      const j = new Date(datum).getFullYear();
      return j < min ? j : min;
    }, huidig);
    const jaren = [];
    for (let j = huidig; j >= vroegste; j--) jaren.push(j);
    return jaren;
  }, [beleggingen, verkochteBeleggingen]);

  if (beleggingen.length === 0) {
    return (
      <div style={{ padding: '0 0 40px' }}>
        <div className="page-header" style={{ marginBottom: 24 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
            <SidebarToggleKnop onToggleSidebar={onToggleSidebar} sidebarCollapsed={sidebarCollapsed} />
            <h1>Dividend</h1>
          </div>
        </div>
        <div style={{ padding: '0 32px' }}>
          <div className="empty-state card"><h3>Nog geen beleggingen</h3><p>Voeg beleggingen toe om dividenddata te zien</p></div>
        </div>
      </div>
    );
  }

  return (
    <div style={{ padding: '0 0 60px' }}>
      {/* Header */}
      <div className="page-header" style={{ marginBottom: 24 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
          <SidebarToggleKnop onToggleSidebar={onToggleSidebar} sidebarCollapsed={sidebarCollapsed} />
          <h1>Dividend</h1>
        </div>
        {/* Jaar dropdown */}
        <div style={{ position: 'relative' }}>
          <button onClick={() => setJaarDropdown(o => !o)} style={{
            display: 'flex', alignItems: 'center', gap: 8, padding: '8px 16px',
            border: '1px solid var(--border)', borderRadius: 8, background: 'var(--bg)',
            cursor: 'pointer', fontSize: 14, fontWeight: 600, fontFamily: 'inherit'
          }}>
            {jaar} <span style={{ fontSize: 10 }}>▼</span>
          </button>
          {jaarDropdown && (
            <div style={{
              position: 'absolute', right: 0, top: '100%', marginTop: 4, background: 'white',
              border: '1px solid var(--border)', borderRadius: 8, boxShadow: 'var(--shadow-md)',
              zIndex: 20, overflow: 'hidden', minWidth: 100
            }}>
              {beschikbareJaren.map(j => (
                <div key={j} onClick={() => { setJaar(j); setJaarDropdown(false); }}
                  style={{
                    padding: '9px 16px', cursor: 'pointer', fontSize: 13,
                    fontWeight: j === jaar ? 700 : 400,
                    background: j === jaar ? 'var(--accent-bg)' : 'transparent',
                    color: j === jaar ? 'var(--accent)' : 'var(--text-primary)'
                  }}
                  onMouseEnter={e => { if (j !== jaar) e.currentTarget.style.background = 'var(--bg)'; }}
                  onMouseLeave={e => { if (j !== jaar) e.currentTarget.style.background = 'transparent'; }}
                >{j}</div>
              ))}
            </div>
          )}
        </div>
      </div>

      <div style={{ padding: '0 32px', display: 'flex', flexDirection: 'column', gap: 20 }}>

        {/* ── Rij 1: Rendement + Dividend ── */}
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 20 }}>

          {/* Rendement card */}
          <div className="card">
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 20 }}>
              <div style={{ fontSize: 16, fontWeight: 700 }}>Rendement</div>
              <button onClick={() => setRendementInfo(true)} style={{
                background: 'transparent', border: 'none', cursor: 'pointer',
                color: 'var(--text-muted)', padding: 2
              }}><Info size={17} /></button>
            </div>
            <div style={{ marginBottom: 16 }}>
              <div style={{ fontSize: 13, color: 'var(--text-muted)', marginBottom: 4 }}>Dividendrendement</div>
              <div style={{ fontSize: 24, fontWeight: 700 }}>{getal(dividendRendement, 2)}%</div>
            </div>
            <div>
              <div style={{ fontSize: 13, color: 'var(--text-muted)', marginBottom: 4 }}>Rendement op aankoopwaarde</div>
              <div style={{ fontSize: 16, fontWeight: 600 }}>{getal(rendementOpAankoop, 2)}%</div>
            </div>
          </div>

          {/* Dividend card */}
          <div className="card">
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 20 }}>
              <div style={{ fontSize: 16, fontWeight: 700 }}>Dividend</div>
              <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                <div style={{ display: 'flex', gap: 2 }}>
                  {['Bruto', 'Netto'].map(m => (
                    <button key={m} onClick={() => setModus(m.toLowerCase())} style={{
                      padding: '4px 10px', borderRadius: 6, border: '1px solid var(--border)',
                      background: modus === m.toLowerCase() ? 'var(--text-primary)' : 'transparent',
                      color: modus === m.toLowerCase() ? 'var(--bg-white)' : 'var(--text-secondary)',
                      fontSize: 12, fontWeight: 500, cursor: 'pointer', fontFamily: 'inherit'
                    }}>{m}</button>
                  ))}
                </div>
                <button onClick={() => setDividendInfo(true)} style={{
                  background: 'transparent', border: 'none', cursor: 'pointer', color: 'var(--text-muted)', padding: 2
                }}><Info size={17} /></button>
              </div>
            </div>
            <div style={{ marginBottom: 16 }}>
              <div style={{ fontSize: 13, color: 'var(--text-muted)', marginBottom: 4 }}>Ontvangen in {jaar} ({modus})</div>
              <div style={{ fontSize: 24, fontWeight: 700 }}>€{fmt2(ontvangen)}</div>
              {geschat > 0.005 && (
                <div style={{ fontSize: 12, color: 'var(--text-muted)', marginTop: 2 }}>
                  waarvan €{fmt2(geschat)} geschat (geen gegevens van de bron; telt niet mee in de grafieken)
                </div>
              )}
              {uitsplitsing && uitsplitsing.bruto > 0.005 && (() => {
                // Van bruto naar netto, als nette "rekensom" in een zacht kader
                const rij = { display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', gap: 16, padding: '5px 0' };
                const bedrag = { fontVariantNumeric: 'tabular-nums', whiteSpace: 'nowrap' };
                return (
                  <div style={{ marginTop: 14, padding: '8px 14px', background: 'var(--bg)', borderRadius: 10, fontSize: 13, color: 'var(--text-secondary)' }}>
                    <div style={rij}>
                      <span>Bruto dividend</span>
                      <span style={{ ...bedrag, color: 'var(--text-primary)' }}>€{fmt2(uitsplitsing.bruto)}</span>
                    </div>
                    <div style={rij}>
                      <span>Buitenlandse bronheffing</span>
                      <span style={bedrag}>{uitsplitsing.bron > 0.005 ? `− €${fmt2(uitsplitsing.bron)}` : '€0,00'}</span>
                    </div>
                    <div style={rij}>
                      <span>Roerende voorheffing (30%)</span>
                      <span style={bedrag}>− €{fmt2(uitsplitsing.rv)}</span>
                    </div>
                    <div style={{ ...rij, borderTop: '1px solid var(--border)', marginTop: 4, paddingTop: 9, fontWeight: 600, color: 'var(--text-primary)' }}>
                      <span>Netto ontvangen</span>
                      <span style={bedrag}>€{fmt2(uitsplitsing.netto)}</span>
                    </div>
                  </div>
                );
              })()}
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', gap: 16, padding: '0 14px', fontSize: 13 }}>
              <span style={{ color: 'var(--text-muted)' }}>Totaal verwacht dit jaar ({modus})</span>
              <span style={{ fontSize: 15, fontWeight: 600, fontVariantNumeric: 'tabular-nums' }}>€{fmt2(verwacht)}</span>
            </div>
          </div>
        </div>

        {/* ── Dividend per maand ── */}
        <div className="card">
          <div style={{ fontSize: 16, fontWeight: 700, marginBottom: 4 }}>Dividend per maand</div>
          <div style={{ fontSize: 13, color: 'var(--text-muted)', marginBottom: 20 }}>Voor {jaar}</div>
          <div style={{ height: 220 }}>
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={maandData} margin={{ top: 4, right: 0, left: 0, bottom: 0 }} barSize={28}>
                <CartesianGrid strokeDasharray="3 3" stroke="var(--border-light)" vertical={false} />
                <XAxis dataKey="label" tick={{ fontSize: 12, fill: 'var(--text-muted)' }} axisLine={false} tickLine={false} />
                <YAxis tick={{ fontSize: 11, fill: 'var(--text-muted)' }} axisLine={false} tickLine={false}
                  tickFormatter={v => v === 0 ? '0' : `€${getal(v, 1)}`} />
                <Tooltip
                  content={({ active, payload, label }) => {
                    if (!active || !payload?.length || !payload[0].value) return null;
                    return (
                      <div style={{
                        background: 'white', border: '1px solid var(--border)', borderRadius: 8,
                        padding: '8px 12px', fontSize: 13, boxShadow: 'var(--shadow-md)'
                      }}>
                        <div style={{ color: 'var(--text-muted)', marginBottom: 2 }}>{label} {jaar}</div>
                        <div style={{ fontWeight: 700, color: ACCENT }}>€{fmt2(payload[0].value)}</div>
                      </div>
                    );
                  }}
                />
                <Bar dataKey="waarde" radius={[4, 4, 0, 0]}>
                  {maandData.map((d, i) => (
                    <Cell key={i} fill={d.waarde > 0 ? ACCENT : 'var(--border-light)'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* ── Per belegging ── */}
        <div className="card" style={{ padding: 0, overflow: 'hidden' }}>
          <div style={{ padding: '18px 24px 14px', borderBottom: '1px solid var(--border-light)' }}>
            <div style={{ fontSize: 16, fontWeight: 700 }}>Per belegging</div>
          </div>
          {/* Kolomhoofden */}
          <div style={{
            display: 'grid', gridTemplateColumns: '2.5fr 1fr 1.4fr 1.6fr 0.8fr',
            padding: '8px 24px', borderBottom: '1px solid var(--border-light)',
            fontSize: 12, fontWeight: 600, color: 'var(--text-muted)'
          }}>
            <span>Naam</span>
            <span style={{ textAlign: 'right' }}>Rendement</span>
            <span style={{ textAlign: 'right' }}>Rendement op aankoopwaarde</span>
            <span style={{ textAlign: 'right' }}>Verwacht jaarlijks dividend</span>
            <span style={{ textAlign: 'right' }}>Ontvangen</span>
          </div>
          {perBelegging.length === 0 ? (
            <div style={{ padding: '24px', textAlign: 'center', color: 'var(--text-muted)', fontSize: 13 }}>
              Geen dividenddata beschikbaar voor {jaar}
            </div>
          ) : perBelegging.map(b => (
            <div key={b.id} style={{
              display: 'grid', gridTemplateColumns: '2.5fr 1fr 1.4fr 1.6fr 0.8fr',
              padding: '14px 24px', borderBottom: '1px solid var(--border-light)', alignItems: 'center',
            }}
              onMouseEnter={e => e.currentTarget.style.background = 'var(--bg)'}
              onMouseLeave={e => e.currentTarget.style.background = 'transparent'}
            >
              <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                <EffectLogoKlein b={b} />
                <div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                    <span style={{ fontWeight: 600, fontSize: 14 }}>{b.naam}</span>
                    {b.verkocht && (
                      <span style={{ fontSize: 10, padding: '1px 6px', background: 'var(--border-light)', borderRadius: 4, color: 'var(--text-muted)', fontWeight: 600 }}>Verkocht</span>
                    )}
                    {b.geschat && (
                      <span title="Geen gegevens van de bron: schatting op basis van het gebruikelijke dividend" style={{ fontSize: 9, padding: '1px 5px', background: 'var(--border-light)', borderRadius: 4, color: 'var(--text-muted)', fontWeight: 700 }}>GESCHAT</span>
                    )}
                    {b.liveData && (
                      <span title="Live data via Finnhub" style={{ fontSize: 9, padding: '1px 5px', background: '#dcfce7', borderRadius: 4, color: '#16a34a', fontWeight: 700 }}>LIVE</span>
                    )}
                  </div>
                  <div style={{ fontSize: 12, color: 'var(--text-muted)' }}>
                    {b.symbol}
                    {b.bronheffing?.land && (
                      <span title="Buitenlandse bronheffing: wordt ingehouden vóór de Belgische 30% roerende voorheffing">
                        {' · '}{b.bronheffing.land}{b.bronheffing.tarief > 0 ? ` · ${procent(b.bronheffing.tarief)} bronheffing` : ' · geen bronheffing'}
                      </span>
                    )}
                  </div>
                </div>
              </div>
              <div style={{ textAlign: 'right', fontSize: 13, fontWeight: 500 }}>
                {b.rendement > 0 ? `${getal(b.rendement, 2)}%` : '—'}
              </div>
              <div style={{ textAlign: 'right', fontSize: 13, fontWeight: 500 }}>
                {b.rendementAankoop > 0 ? `${getal(b.rendementAankoop, 2)}%` : '—'}
              </div>
              <div style={{ textAlign: 'right', fontSize: 13, fontWeight: 600 }}>
                €{fmt2(b.verwachtJaarlijks)}
              </div>
              <div style={{ textAlign: 'right', fontSize: 13, fontWeight: 600, color: b.ontvangen > 0 ? 'var(--green)' : 'var(--text-primary)' }}>
                €{fmt2(b.ontvangen)}
              </div>
            </div>
          ))}
          {/* Beleggingen zonder data */}
          {(zonderData.length > 0 || geenDividend.length > 0) && (
            <div style={{ padding: '12px 24px', fontSize: 12, color: 'var(--text-muted)', borderTop: '1px solid var(--border-light)', display: 'flex', flexDirection: 'column', gap: 4 }}>
              {geenDividend.length > 0 && (
                <span>🚫 Keert geen dividend uit: {geenDividend.join(', ')}</span>
              )}
              {zonderData.length > 0 && (
                <span>🕐 Nog geen dividend dit jaar: {zonderData.join(', ')}</span>
              )}
            </div>
          )}
        </div>
      </div>

      {/* ── Info modals ── */}
      {rendementInfo && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(15,23,42,0.4)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}
          onClick={() => setRendementInfo(false)}>
          <div style={{ background: 'white', borderRadius: 16, padding: 32, width: 460, maxWidth: '90vw', boxShadow: 'var(--shadow-lg)' }}
            onClick={e => e.stopPropagation()}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
              <h2 style={{ fontSize: 18, fontWeight: 700 }}>Dividendrendement</h2>
              <button onClick={() => setRendementInfo(false)} style={{ background: 'transparent', border: 'none', cursor: 'pointer', color: 'var(--text-muted)' }}><X size={18} /></button>
            </div>
            <p style={{ fontSize: 14, color: 'var(--text-secondary)', lineHeight: 1.65, marginBottom: 12 }}>
              <strong>Dividendrendement</strong> = jaarlijks dividend ÷ huidige marktwaarde × 100. Dit toont hoeveel je ontvangt in verhouding tot wat je belegging vandaag waard is.
            </p>
            <p style={{ fontSize: 14, color: 'var(--text-secondary)', lineHeight: 1.65 }}>
              <strong>Rendement op aankoopwaarde</strong> = jaarlijks dividend ÷ je aankoopprijs × 100. Dit toont het rendement op basis van wat je ooit betaald hebt — ook wel "yield on cost" genoemd.
            </p>
          </div>
        </div>
      )}
      {dividendInfo && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(15,23,42,0.4)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}
          onClick={() => setDividendInfo(false)}>
          <div style={{ background: 'white', borderRadius: 16, padding: 32, width: 460, maxWidth: '90vw', boxShadow: 'var(--shadow-lg)' }}
            onClick={e => e.stopPropagation()}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
              <h2 style={{ fontSize: 18, fontWeight: 700 }}>Bruto vs Netto dividend</h2>
              <button onClick={() => setDividendInfo(false)} style={{ background: 'transparent', border: 'none', cursor: 'pointer', color: 'var(--text-muted)' }}><X size={18} /></button>
            </div>
            <p style={{ fontSize: 14, color: 'var(--text-secondary)', lineHeight: 1.65, marginBottom: 12 }}>
              <strong>Bruto</strong> is het dividend vóór belastingen — het bedrag dat het bedrijf uitkeert.
            </p>
            <p style={{ fontSize: 14, color: 'var(--text-secondary)', lineHeight: 1.65, marginBottom: 12 }}>
              <strong>Netto</strong> is wat je effectief ontvangt. Eerst houdt het land van het bedrijf een <strong>buitenlandse bronheffing</strong> in (bv. VS 15%, Nederland 15%, Duitsland 26,375%; Ierse en Luxemburgse ETF's en Belgische aandelen 0%). Daarna houdt België <strong>30% roerende voorheffing</strong> in op wat overblijft. Op $1,00 bruto van een Amerikaans aandeel ontvang je zo $0,595 netto.
            </p>
            <p style={{ fontSize: 14, color: 'var(--text-secondary)', lineHeight: 1.65, marginBottom: 12 }}>
              <strong>Tip:</strong> een deel van je dividenden uit aandelen is per jaar vrijgesteld (ruim €800, jaarlijks geïndexeerd). De Belgische 30% op dat deel kan je terugvragen via je belastingaangifte. De buitenlandse bronheffing krijg je zo niet terug. Voor de VS geldt 15% enkel als je broker je W-8BEN-formulier heeft; anders 30%.
            </p>
            <p style={{ fontSize: 14, color: 'var(--text-secondary)', lineHeight: 1.65 }}>
              Accumulerende ETFs (zoals VWCE, IWDA) keren geen dividend uit maar herbeleggen het automatisch — die zie je niet terug in dit overzicht.
            </p>
          </div>
        </div>
      )}
    </div>
  );
}
